    /**
     * "Historique" — Graphique temporel avec points reliés (style original InBody).
     * Structure : tableau avec une colonne par mesure historique.
     * Chaque métrique (Poids, MMS, TGC, Ratio EEC) occupe une ligne.
     * Dans chaque cellule : point ● centré au-dessus de la valeur numérique.
     * La ligne du bas affiche les dates (axe X).
     * La colonne la plus à droite = mesure actuelle, mise en évidence.
     */
    /**
     * "Historique" — Graphique temporel avec lignes de tendance (courbes brisées)
     * reproduisant fidèlement l original InBody.
     *
     * Structure visuelle :
     *   - 4 métriques : Poids, MMS, TGC, Ratio EEC — chacune sur sa propre ligne
     *   - Pour chaque métrique : mini-graphique XObject dessiné sur PdfCanvas
     *       * Ligne brisée reliant tous les points historiques
     *       * Points ronds pleins (cercles) a chaque mesure
     *       * Valeur numérique sous chaque point
     *   - Axe X en bas : dates des mesures
     *   - Colonne valeur actuelle mise en évidence a droite
     */
    private Table secHistorique(InBodyMeasurement m, List<InBodyReportSummary> history,
                                PdfFont bold, PdfFont regular, PdfDocument pdf) {
        Table s = wrap();
        s.addCell(secTitleCell("Historique", bold));

        // Legende
        s.addCell(nb(1).add(new Paragraph()
                .add(new Text("●").setFont(bold).setFontSize(8).setFontColor(DARK))
                .add(new Text(" Recent  ").setFont(regular).setFontSize(5).setFontColor(MID_GRAY))
                .add(new Text("□").setFont(regular).setFontSize(6).setFontColor(MID_GRAY))
                .add(new Text(" Total").setFont(regular).setFontSize(5).setFontColor(MID_GRAY))
                .setMargin(0)));

        int maxH  = Math.min(history.size(), 5);
        List<InBodyReportSummary> items = history.isEmpty()
                ? List.of() : history.subList(0, maxH);

        // Toutes les mesures = items + mesure actuelle
        int n = items.size() + 1;

        // Construire les 4 series de valeurs
        double[] poids = new double[n];
        double[] mms   = new double[n];
        double[] tgc   = new double[n];
        double[] eec   = new double[n];
        String[] dates = new String[n];

        for (int i = 0; i < items.size(); i++) {
            InBodyReportSummary r = items.get(i);
            poids[i] = r.getWeight() != null ? r.getWeight() : 0;
            mms[i]   = r.getSkeletalMuscleMass() != null ? r.getSkeletalMuscleMass() : 0;
            tgc[i]   = r.getPercentBodyFat() != null ? r.getPercentBodyFat() : 0;
            eec[i]   = 0; // non disponible dans InBodyReportSummary
            dates[i] = r.getTestDateTime() != null ? r.getTestDateTime().format(SHORT_FMT) : "-";
        }
        // Mesure actuelle (derniere colonne)
        int last = n - 1;
        poids[last] = m.getWeight() != null ? m.getWeight() : 0;
        mms[last]   = m.getSkeletalMuscleMass() != null ? m.getSkeletalMuscleMass() : 0;
        tgc[last]   = m.getPercentBodyFat() != null ? m.getPercentBodyFat() : 0;
        eec[last]   = m.getEcwTbw() != null ? m.getEcwTbw() : 0;
        dates[last] = m.getTestDateTime() != null ? m.getTestDateTime().format(SHORT_FMT) : "-";

        // Dessiner les 4 graphiques (un par metrique)
        String[] labels  = {"Poids (kg)", "MMS (kg)", "TGC (%)", "Ratio EEC"};
        double[][] series = {poids, mms, tgc, eec};

        Table chart = new Table(UnitValue.createPercentArray(new float[]{100}))
                .setWidth(UnitValue.createPercentValue(100));

        for (int mi = 0; mi < 4; mi++) {
            chart.addCell(nb(0).add(
                    buildHistogramLine(labels[mi], series[mi], dates, n, mi, bold, regular, pdf)));
        }

        s.addCell(nb(0).add(chart));
        return s;
    }

    /**
     * Construit un mini-graphique linéaire pour une série historique.
     * Utilise PdfFormXObject pour dessiner la ligne et les points.
     * En-dessous : tableau des valeurs numeriques + dates.
     */
    private Table buildHistogramLine(String label, double[] vals, String[] dates,
                                     int n, int metricIdx,
                                     PdfFont bold, PdfFont regular, PdfDocument pdf) {
        Table wrap = new Table(UnitValue.createPercentArray(new float[]{100}))
                .setWidth(UnitValue.createPercentValue(100))
                .setMarginBottom(2);

        // Sous-titre de la metrique
        wrap.addCell(nb(1).setBackgroundColor(HDR_BG)
                .add(p(label, bold, 6f)));

        if (n < 1) {
            wrap.addCell(nb(1).add(p("-", regular, 6f).setFontColor(MID_GRAY)));
            return wrap;
        }

        // Determiner min/max pour normaliser la hauteur
        double minV = vals[0], maxV = vals[0];
        for (double v : vals) { if (v < minV) minV = v; if (v > maxV) maxV = v; }
        double range = maxV - minV;
        if (range < 0.001) { minV -= 1; maxV += 1; range = 2; }

        float chartW = 340f; // largeur canvas (pts)
        float chartH = 35f;  // hauteur canvas (pts)
        float padL   = 8f;
        float padR   = 8f;
        float padT   = 6f;
        float padB   = 6f;
        float plotW  = chartW - padL - padR;
        float plotH  = chartH - padT - padB;

        // Calculer coordonnees X/Y de chaque point
        float[] px = new float[n];
        float[] py = new float[n];
        float colW = n > 1 ? plotW / (n - 1) : plotW;
        for (int i = 0; i < n; i++) {
            px[i] = padL + (n > 1 ? i * colW : plotW / 2f);
            py[i] = padB + (float)((vals[i] - minV) / range * plotH);
        }

        try {
            PdfFormXObject xobj = new PdfFormXObject(new Rectangle(chartW, chartH));
            PdfCanvas pc = new PdfCanvas(xobj, pdf);

            // Fond blanc
            pc.setFillColor(VLIGHT_GRAY);
            pc.rectangle(0, 0, chartW, chartH);
            pc.fill();

            // Ligne de reference horizontale (mi-hauteur)
            pc.setStrokeColor(LIGHT_GRAY);
            pc.setLineWidth(0.3f);
            pc.moveTo(padL, padB + plotH / 2);
            pc.lineTo(padL + plotW, padB + plotH / 2);
            pc.stroke();

            // Ligne brisee reliant les points
            if (n > 1) {
                pc.setStrokeColor(DARK_GRAY);
                pc.setLineWidth(0.8f);
                pc.moveTo(px[0], py[0]);
                for (int i = 1; i < n; i++) pc.lineTo(px[i], py[i]);
                pc.stroke();
            }

            // Points circulaires
            PdfFont f = PdfFontFactory.createFont(StandardFonts.HELVETICA);
            for (int i = 0; i < n; i++) {
                boolean isLast = (i == n - 1);
                pc.setFillColor(isLast ? DARK : MID_GRAY);
                pc.circle(px[i], py[i], isLast ? 2.8f : 2f);
                pc.fill();
            }
            pc.release();

            com.itextpdf.layout.element.Image img =
                    new com.itextpdf.layout.element.Image(xobj)
                            .setWidth(UnitValue.createPercentValue(100))
                            .setAutoScale(false);
            wrap.addCell(nb(0).add(img));

        } catch (Exception e) {
            log.warn("Historique chart error: {}", e.getMessage());
            wrap.addCell(nb(1).add(p("(graphique indisponible)", regular, 5f).setFontColor(MID_GRAY)));
        }

        // Ligne de valeurs numeriques + dates sous le graphique
        float[] colWidths = new float[n];
        java.util.Arrays.fill(colWidths, 100f / n);
        Table dataRow = new Table(UnitValue.createPercentArray(colWidths)).setWidth(UnitValue.createPercentValue(100));
        for (int i = 0; i < n; i++) {
            boolean isLast = (i == n - 1);
            String valStr = metricIdx == 3 ? fmt3(vals[i]) : fmt(vals[i]);
            Cell dc = new Cell().setBorder(Border.NO_BORDER)
                    .setBorderTop(new SolidBorder(LIGHT_GRAY, 0.3f))
                    .setPadding(1).setTextAlignment(TextAlignment.CENTER);
            dc.add(p(valStr, isLast ? bold : regular, isLast ? 6.5f : 6f)
                    .setFontColor(isLast ? DARK : DARK_GRAY));
            dc.add(p(dates[i], regular, 4.5f).setFontColor(MID_GRAY));
            dataRow.addCell(dc);
        }
        wrap.addCell(nb(0).add(dataRow));
        return wrap;
    }

    @FunctionalInterface
    interface HistExtractor { String extract(InBodyReportSummary r); }

    /**
     * CORRECTION 2 — Historique style timeline original :
     * Chaque mesure passée s'affiche avec un gros point ● centré au-dessus de la valeur.
     * La valeur actuelle (la plus récente) est mise en évidence à droite.
     * Les dates sont affichées tout en bas de la colonne correspondante.
     * Ce style reproduit exactement les courbes d'évolution ponctuelles de l'original.
     */
    private void histRow(Table t, String label, String sub,
                         List<InBodyReportSummary> items,
                         HistExtractor ex, String current,
                         PdfFont bold, PdfFont regular) {
        // Label à gauche
        Cell lc = nb(1);
        lc.add(p(label, bold, 7.5f));
        for (String s : sub.split("\n")) if (!s.isEmpty())
            lc.add(p(s, regular, 5).setFontColor(MID_GRAY));
        t.addCell(lc);

        if (items.isEmpty()) {
            // Pas d'historique : affiche juste la mesure actuelle avec gros point
            Cell dc = nb(1).setTextAlignment(TextAlignment.CENTER);
            dc.add(p("●", bold, 14).setFontColor(DARK));
            dc.add(p(current, bold, 9));
            t.addCell(dc);
        } else {
            // Mesures historiques : point + valeur, taille croissante vers la droite
            for (int i = 0; i < items.size(); i++) {
                InBodyReportSummary it = items.get(i);
                boolean isLatest = (i == items.size() - 1);
                Cell dc = nb(1).setTextAlignment(TextAlignment.CENTER);
                // Point plus grand pour la mesure la plus récente
                float dotSize = isLatest ? 14f : 11f;
                dc.add(p("●", bold, dotSize).setFontColor(DARK));
                dc.add(p(ex.extract(it), isLatest ? bold : regular,
                        isLatest ? 8.5f : 7f));
                t.addCell(dc);
            }
        }
        // Valeur actuelle en évidence à droite
        t.addCell(nb(1).setTextAlignment(TextAlignment.RIGHT)
                .setVerticalAlignment(VerticalAlignment.MIDDLE)
                .add(p(current, bold, 10)));
    }

    /**
     * "Impédance" — tableau 6 fréquences × 5 segments + colonne fréquence
     * Identique à l'original (fond alterné, valeurs centrées)
     */
    private Table secImpedance(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Impédance", bold));

        Table t = new Table(UnitValue.createPercentArray(new float[]{17, 16, 16, 17, 17, 17}))
                .setWidth(UnitValue.createPercentValue(100));

        // En-tête
        for (String h : new String[]{"Z(Ω)", "MSD", "MSG", "TR", "MID", "MIG"})
            t.addCell(new Cell().setBackgroundColor(HDR_BG)
                    .setBorder(new SolidBorder(LIGHT_GRAY, 0.3f))
                    .setPadding(2).setTextAlignment(TextAlignment.CENTER)
                    .add(p(h, bold, 6.5f)));

        // Lignes de fréquences (alternées)
        impRow(t, "1 kHz",    m.getV1khzRaImpedance(),    m.getV1khzLaImpedance(),    m.getV1khzTrImpedance(),    m.getV1khzRlImpedance(),    m.getV1khzLlImpedance(),    regular, false);
        impRow(t, "5 kHz",    m.getV5khzRaImpedance(),    m.getV5khzLaImpedance(),    m.getV5khzTrImpedance(),    m.getV5khzRlImpedance(),    m.getV5khzLlImpedance(),    regular, true);
        impRow(t, "50 kHz",   m.getV50khzRaImpedance(),   m.getV50khzLaImpedance(),   m.getV50khzTrImpedance(),   m.getV50khzRlImpedance(),   m.getV50khzLlImpedance(),   regular, false);
        impRow(t, "250 kHz",  m.getV250khzRaImpedance(),  m.getV250khzLaImpedance(),  m.getV250khzTrImpedance(),  m.getV250khzRlImpedance(),  m.getV250khzLlImpedance(),  regular, true);
        impRow(t, "500 kHz",  m.getV500khzRaImpedance(),  m.getV500khzLaImpedance(),  m.getV500khzTrImpedance(),  m.getV500khzRlImpedance(),  m.getV500khzLlImpedance(),  regular, false);
        impRow(t, "1000 kHz", m.getV1000khzRaImpedance(), m.getV1000khzLaImpedance(), m.getV1000khzTrImpedance(), m.getV1000khzRlImpedance(), m.getV1000khzLlImpedance(), regular, true);

        s.addCell(nb(0).add(t));
        return s;
    }

    private void impRow(Table t, String freq, Double ra, Double la, Double tr,
                        Double rl, Double ll, PdfFont regular, boolean stripe) {
        DeviceRgb bg = stripe ? STRIPE_B : STRIPE_A;
        for (String v : new String[]{freq, fmt(ra), fmt(la), fmt(tr), fmt(rl), fmt(ll)})
            t.addCell(new Cell().setBackgroundColor(bg)
                    .setBorder(new SolidBorder(LIGHT_GRAY, 0.2f))
                    .setPadding(2).setTextAlignment(TextAlignment.CENTER)
                    .add(p(v, regular, 6)));
    }

    // ══════════════════════════════════════════════════════════════════════════
    // SECTIONS — PAGE 1 DROITE
    // ══════════════════════════════════════════════════════════════════════════

    /**
     * "Score InBody" — grand chiffre centré + barre de score 0/60/100
     */
    private Table secScoreInBody(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Score InBody", bold));

        int score = m.getInbodyScore() != null ? m.getInbodyScore() : 0;

        Cell cc = nb(4).setTextAlignment(TextAlignment.CENTER)
                .setBackgroundColor(new DeviceRgb(240, 246, 253));

        DeviceRgb scoreNumColor = score >= 80 ? FILL_HIGH : score >= 60 ? FILL_NORMAL : FILL_LOW;
        cc.add(p(String.valueOf(score), bold, 44).setFontColor(scoreNumColor));
        cc.add(p("/100 Points", regular, 9).setFontColor(new DeviceRgb(80, 120, 170)));

        // Barre de score
        cc.add(buildScoreBar(score, bold, regular));

        cc.add(new LineSeparator(new SolidLine(0.3f)).setMarginTop(4).setMarginBottom(2));
        cc.add(p("* Le score InBody reflète l'évaluation de la composition\n" +
                        "corporelle en un chiffre. Une personne musclée peut obtenir plus de 100 points.",
                regular, 5.5f).setFontColor(MID_GRAY));

        s.addCell(cc);
        return s;
    }

    private Table buildScoreBar(int score, PdfFont bold, PdfFont regular) {
        Table wrap = new Table(UnitValue.createPercentArray(new float[]{100}))
                .setWidth(UnitValue.createPercentValue(100)).setMarginTop(4);

        // Graduations
        Table scale = new Table(UnitValue.createPercentArray(new float[]{60, 20, 20})).setWidth(UnitValue.createPercentValue(100));
        scale.addCell(nb(0).add(p("0", regular, 5).setFontColor(MID_GRAY)));
        scale.addCell(nb(0).setTextAlignment(TextAlignment.CENTER).add(p("60", regular, 5).setFontColor(MID_GRAY)));
        scale.addCell(nb(0).setTextAlignment(TextAlignment.RIGHT).add(p("100", regular, 5).setFontColor(MID_GRAY)));
        wrap.addCell(nb(0).add(scale));

        // 3 zones colorées : rouge (0-60) | bleu (60-80) | vert (80-100)
        Table bar = new Table(UnitValue.createPercentArray(new float[]{60, 20, 20})).setWidth(UnitValue.createPercentValue(100));
        bar.addCell(new Cell().setHeight(8).setBackgroundColor(ZONE_LOW).setBorder(Border.NO_BORDER));
        bar.addCell(new Cell().setHeight(8).setBackgroundColor(ZONE_NORMAL).setBorder(Border.NO_BORDER));
        bar.addCell(new Cell().setHeight(8).setBackgroundColor(ZONE_HIGH).setBorder(Border.NO_BORDER));
        wrap.addCell(nb(0).add(bar));

        // Marqueur ▼ coloré selon le score
        DeviceRgb scoreColor = score >= 80 ? FILL_HIGH : score >= 60 ? FILL_NORMAL : FILL_LOW;
        float pos = Math.max(2f, Math.min(97f, score));
        float ml = pos - 3f, mr = Math.max(0.5f, 100f - pos - 3f);
        Table mk = new Table(UnitValue.createPercentArray(new float[]{ml, 6, mr})).setWidth(UnitValue.createPercentValue(100));
        mk.addCell(nb(0));
        mk.addCell(nb(0).setTextAlignment(TextAlignment.CENTER).add(p("▼", regular, 8).setFontColor(scoreColor)));
        mk.addCell(nb(0));
        wrap.addCell(nb(0).add(mk));
        return wrap;
    }

    /**
     * "Surface de graisse viscérale" — valeur SGV + graphique SGV par âge
     */
    private Table secSGV(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Surface de graisse viscérale", bold));

        // Valeur principale
        Table top = new Table(UnitValue.createPercentArray(new float[]{55, 45}))
                .setWidth(UnitValue.createPercentValue(100));
        Cell tl = nb(2);
        tl.add(p("SGV(cm²)", regular, 6.5f).setFontColor(MID_GRAY));
        tl.add(p(fmt(m.getVfaVisceralFatArea()), bold, 15).setFontColor(RED));
        top.addCell(tl);
        Cell tr = nb(2);
        if (m.getVflVisceralFatLevel() != null)
            tr.add(p("Niveau : " + m.getVflVisceralFatLevel(), regular, 7));
        top.addCell(tr);

        Cell cc = nb(2);
        cc.add(top);

        // Grille SGV par âge (Y: 0-200, X: 20-80)
        Table chart = new Table(UnitValue.createPercentArray(new float[]{10, 90}))
                .setWidth(UnitValue.createPercentValue(100));

        Cell ya = nb(0).setTextAlignment(TextAlignment.RIGHT);
        for (String label : new String[]{"200", "150", "100", "50", ""})
            ya.add(p(label, regular, 5).setFontColor(MID_GRAY));
        chart.addCell(ya);

        Cell area = nb(1).setBorder(new SolidBorder(LIGHT_GRAY, 0.5f))
                .setBackgroundColor(VLIGHT_GRAY);
        // Grille simplifiée (4×5 cellules)
        Table grid = new Table(UnitValue.createPercentArray(new float[]{25, 25, 25, 25})).setWidth(UnitValue.createPercentValue(100));
        for (int row = 0; row < 5; row++)
            for (int col = 0; col < 4; col++) {
                boolean norm = (row == 1 || row == 2);
                grid.addCell(new Cell().setHeight(9)
                        .setBackgroundColor(norm ? new DeviceRgb(220, 220, 220) : VLIGHT_GRAY)
                        .setBorder(new SolidBorder(LIGHT_GRAY, 0.3f)));
            }
        area.add(grid);
        if (m.getVfaVisceralFatArea() != null && m.getAge() != null)
            area.add(p("✦ " + fmt(m.getVfaVisceralFatArea()) + " cm² (âge " + m.getAge() + ")",
                    bold, 6).setFontColor(DARK));
        // Axe X
        Table xa = new Table(UnitValue.createPercentArray(new float[]{25, 25, 25, 25})).setWidth(UnitValue.createPercentValue(100));
        for (String a : new String[]{"20", "40", "60", "80"})
            xa.addCell(nb(0).setTextAlignment(TextAlignment.CENTER)
                    .add(p(a, regular, 5).setFontColor(MID_GRAY)));
        area.add(xa);
        area.add(p("Âge", regular, 6).setFontColor(MID_GRAY).setTextAlignment(TextAlignment.CENTER));
        chart.addCell(area);
        cc.add(chart);

        s.addCell(cc);
        return s;
    }

