                .setWidth(UnitValue.createPercentValue(100));

        fatRow(t, "MSD", "(Membre Supérieur Droit)",  m.getBfmOfRightArm(), m.getBfmPercentOfRightArm(), bold, regular);
        fatRow(t, "MSG", "(Membre Supérieur Gauche)", m.getBfmOfLeftArm(),  m.getBfmPercentOfLeftArm(),  bold, regular);
        fatRow(t, "TR",  "(Tronc)",                   m.getBfmOfTrunk(),    m.getBfmPercentOfTrunk(),    bold, regular);
        fatRow(t, "MID", "(Membre Inférieur Droit)",  m.getBfmOfRightLeg(), m.getBfmPercentOfRightLeg(), bold, regular);
        fatRow(t, "MIG", "(Membre Inférieur Gauche)", m.getBfmOfLeftLeg(),  m.getBfmPercentOfLeftLeg(),  bold, regular);

        s.addCell(nb(0).add(t));
        return s;
