     */
    private Table secParametresRecherche(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Paramètres de recherche", bold));

        Table t = new Table(UnitValue.createPercentArray(new float[]{48, 30, 22}))
                .setWidth(UnitValue.createPercentValue(100));

        Object[][] rows = {
                {"Eau intracellulaire",         fmt(m.getIntracellularWater()) + " L",          range(m.getIcwLowerLimit(), m.getIcwUpperLimit())},
                {"Eau extracellulaire",          fmt(m.getExtracellularWater()) + " L",          range(m.getEcwLowerLimit(), m.getEcwUpperLimit())},
                {"Métabolisme de Base",          fmt(m.getBmrBasalMetabolicRate()) + " kcal",    range(m.getLowerLimitBmrNormalRange(), m.getUpperLimitBmrNormalRange())},
                {"Rapport taille-hanche",        fmt(m.getWhrWaistHipRatio()),                   range(m.getLowerLimitWhrNormalRange(), m.getUpperLimitWhrNormalRange())},
                {"Masse Cellulaire Active",       fmt(m.getBcmBodyCellMass()) + " kg",           range(m.getLowerLimitBcmNormalRange(), m.getUpperLimitBcmNormalRange())},
                {"Tour de taille",               fmt(m.getMeasuredCircumferenceOfAbdomen()) + " cm", ""},
                {"Surface graisse viscérale",    fmt(m.getVfaVisceralFatArea()) + " cm²",        ""},
                {"Degré de surpoids",            fmt(m.getObesityDegree()) + " %",               range(m.getLowerLimitObesityDegreeNormalRange(), m.getUpperLimitObesityDegreeNormalRange())},
                {"IMS",                          fmt(m.getSmiSkeletalMuscleIndex()) + " kg/m²",  ""},
                {"Apport calorique recommandé",  fmt(m.getRecommendedCalorieIntake()) + " kcal", ""}
        };

        for (int i = 0; i < rows.length; i++) {
            DeviceRgb bg = (i % 2 == 0) ? STRIPE_A : STRIPE_B;
            t.addCell(new Cell().setBackgroundColor(bg).setBorder(Border.NO_BORDER)
                    .setPadding(2).add(p((String) rows[i][0], regular, 6.5f)));
            t.addCell(new Cell().setBackgroundColor(bg).setBorder(Border.NO_BORDER)
                    .setPadding(2).setTextAlignment(TextAlignment.RIGHT)
