    private Table secImpedanceCompact(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Impédance", bold));

        // En-tête avec notation Z(Ω) et les 5 segments
