            hdr.addCell(new Cell().setBackgroundColor(HDR_BG)
                    .setBorder(new SolidBorder(LIGHT_GRAY, 0.3f))
                    .setPadding(2)
                    .setTextAlignment(TextAlignment.CENTER)
                    .add(p(h, bold, 5.5f)));
        s.addCell(nb(0).add(hdr));

        Table t = new Table(UnitValue.createPercentArray(new float[]{18, 16, 16, 16, 17, 17}))
                .setWidth(UnitValue.createPercentValue(100));
        impRowCompact(t, "1 kHz",    m.getV1khzRaImpedance(),    m.getV1khzLaImpedance(),    m.getV1khzTrImpedance(),    m.getV1khzRlImpedance(),    m.getV1khzLlImpedance(),    regular, false);
        impRowCompact(t, "5 kHz",    m.getV5khzRaImpedance(),    m.getV5khzLaImpedance(),    m.getV5khzTrImpedance(),    m.getV5khzRlImpedance(),    m.getV5khzLlImpedance(),    regular, true);
        impRowCompact(t, "50 kHz",   m.getV50khzRaImpedance(),   m.getV50khzLaImpedance(),   m.getV50khzTrImpedance(),   m.getV50khzRlImpedance(),   m.getV50khzLlImpedance(),   regular, false);
        impRowCompact(t, "250 kHz",  m.getV250khzRaImpedance(),  m.getV250khzLaImpedance(),  m.getV250khzTrImpedance(),  m.getV250khzRlImpedance(),  m.getV250khzLlImpedance(),  regular, true);
        impRowCompact(t, "500 kHz",  m.getV500khzRaImpedance(),  m.getV500khzLaImpedance(),  m.getV500khzTrImpedance(),  m.getV500khzRlImpedance(),  m.getV500khzLlImpedance(),  regular, false);
        impRowCompact(t, "1000 kHz", m.getV1000khzRaImpedance(), m.getV1000khzLaImpedance(), m.getV1000khzTrImpedance(), m.getV1000khzRlImpedance(), m.getV1000khzLlImpedance(), regular, true);
        s.addCell(nb(0).add(t));
        return s;
    }

    /** Ligne d impedance a fonte reduite pour la sidebar compacte (28%). */
