    /**
     * "Analyse de l'eau corporelle par segment"
     * 5 segments avec barres % (55–205%)
     */
    private Table secEauParSegment(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Analyse de l'eau corporelle par segment", bold));

        Table hdr = new Table(UnitValue.createPercentArray(new float[]{20, 10, 54, 8, 8}))
                .setWidth(UnitValue.createPercentValue(100)).setBackgroundColor(HDR_BG);
