        hdr.addCell(hdrCell("55   70   85   100   115   130   145   160   175   190   205  %", regular));
        hdr.addCell(hdrCell("Inf.", regular));
        hdr.addCell(hdrCell("Nor.", regular));
        s.addCell(nb(0).add(hdr));

        Table t = new Table(UnitValue.createPercentArray(new float[]{20, 10, 54, 8, 8}))
                .setWidth(UnitValue.createPercentValue(100));

        segWaterRow(t, "Membre\nSup. Droit",
                m.getTbwRightArm(), m.getTbwRightArmLowerLimit(), m.getTbwRightArmUpperLimit(), 55, 205, bold, regular);
        segWaterRow(t, "Membre\nSup. Gauche",
                m.getTbwLeftArm(), m.getTbwLeftArmLowerLimit(), m.getTbwLeftArmUpperLimit(), 55, 205, bold, regular);
        segWaterRow(t, "Tronc",
                m.getTbwTrunk(), m.getTbwTrunkLowerLimit(), m.getTbwTrunkUpperLimit(), 70, 170, bold, regular);
        segWaterRow(t, "Membre\nInf. Droit",
                m.getTbwRightLeg(), m.getTbwRightLegLowerLimit(), m.getTbwRightLegUpperLimit(), 70, 170, bold, regular);
        segWaterRow(t, "Membre\nInf. Gauche",
                m.getTbwLeftLeg(), m.getTbwLeftLegLowerLimit(), m.getTbwLeftLegUpperLimit(), 70, 170, bold, regular);

        s.addCell(nb(0).add(t));
        return s;
    }

    private void segWaterRow(Table t, String label, Double val, Double lo, Double hi,
                             double sMin, double sMax, PdfFont bold, PdfFont regular) {
        Cell lc = nb(1);
        for (String p2 : label.split("\n")) lc.add(p(p2, regular, 6.5f));
        t.addCell(lc);

        t.addCell(nb(1).setTextAlignment(TextAlignment.CENTER)
                .setVerticalAlignment(VerticalAlignment.MIDDLE)
                .add(p(fmt(val), bold, 8)));

        t.addCell(nb(0).add(buildColorBar(val, lo, hi, sMin, sMax, 6, regular)));

        t.addCell(nb(1).setTextAlignment(TextAlignment.CENTER)
                .setVerticalAlignment(VerticalAlignment.MIDDLE)
                .add(p(fmt(lo), regular, 5).setFontColor(MID_GRAY)));
        t.addCell(nb(1).setTextAlignment(TextAlignment.CENTER)
                .setVerticalAlignment(VerticalAlignment.MIDDLE)
                .add(p(fmt(hi), regular, 5).setFontColor(MID_GRAY)));
    }

    /**
     * "Analyse des ratios EEC par segment"
     * Graphique en points pour 5 segments (Bras D/G, Tronc, Jambe D/G)
     * Axe Y : 0.36–0.43
     */
    /**
     * CORRECTION 4 — "Analyse des ratios EEC par segment"
     * Graphique imposant et dédié, centré sur la page 2 gauche.
     * Structure originale :
     *   - Axe Y à gauche avec labels de zones : "Elevé" / "Légèrement élevé" / "Normal"
     *   - Valeurs numériques 0,36–0,43 sur l'axe Y
     *   - 5 colonnes (un par segment) avec le point ● positionné à la bonne hauteur
     *   - Label du segment en bas de chaque colonne
     *   - Valeur numérique affichée sur le point
     * La hauteur du point est calculée proportionnellement à l'axe Y (0,36–0,43).
     */
    private Table secRatiosEECParSegment(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Analyse des ratios EEC par segment", bold));

        String[] segs = {"Bras droit", "Bras gauche", "Tronc", "Jambe droite", "Jambe gauche"};
        Double[] vals = {m.getEcwTbwOfRightArm(), m.getEcwTbwOfLeftArm(),
                m.getEcwTbwOfTrunk(), m.getEcwTbwOfRightLeg(), m.getEcwTbwOfLeftLeg()};

        // Grille graphique : col Y (15%) + 5 colonnes segments (17% chacune)
        Table chart = new Table(UnitValue.createPercentArray(new float[]{13, 87}))
                .setWidth(UnitValue.createPercentValue(100));

        // ── Axe Y gauche : labels numériques + zones textuelles ──────────────
        Cell ya = nb(0).setTextAlignment(TextAlignment.RIGHT).setPaddingRight(2);
        // 8 valeurs Y de 0,43 (haut) à 0,36 (bas)
        String[] yLabels = {"0,43","0,42","0,41","0,40","0,39","0,38","0,37","0,36"};
        // Zones textuelles (positionnées sur l'axe)
        // 0,41+ = Elevé ; 0,39–0,41 = Légèrement élevé ; <0,39 = Normal
        ya.add(p("Elevé", bold, 5).setFontColor(DARK));
        ya.add(p("", regular, 2));
        ya.add(p("Leg. eleve", bold, 5).setFontColor(DARK));
        ya.add(p("", regular, 2));
        ya.add(p("Normal", bold, 5).setFontColor(DARK));
        ya.add(new LineSeparator(new SolidLine(0.3f)).setMarginTop(1).setMarginBottom(1));
        for (String lbl : yLabels)
            ya.add(p(lbl, regular, 5).setFontColor(MID_GRAY));
        chart.addCell(ya);

        // ── Zone de tracé : 5 colonnes ────────────────────────────────────────
        // Y range : 0,36 (bas) → 0,43 (haut), soit 7 divisions de 0,01
        double yMin = 0.36, yMax = 0.43, yRange = yMax - yMin;
        int totalRows = 8; // nombre de lignes de la grille

        Table plot = new Table(UnitValue.createPercentArray(new float[]{20, 20, 20, 20, 20}))
                .setWidth(UnitValue.createPercentValue(100))
                .setBorder(new SolidBorder(LIGHT_GRAY, 0.3f));

        for (int i = 0; i < 5; i++) {
            double v = vals[i] != null ? vals[i] : 0.385;
            // Position relative : 0=bas, 1=haut
            double relPos = Math.max(0.0, Math.min(1.0, (v - yMin) / yRange));
            // Espace vide au-dessus du point (en unités de lignes de grille)
            int rowsAbove = (int) Math.round((1.0 - relPos) * (totalRows - 1));
            int rowsBelow = (totalRows - 1) - rowsAbove;
            if (rowsAbove < 0) rowsAbove = 0;
            if (rowsBelow < 0) rowsBelow = 0;

            // Fond coloré selon la zone
            DeviceRgb zoneBg;
            if (v >= 0.41)       zoneBg = new DeviceRgb(215, 215, 215); // élevé
            else if (v >= 0.39)  zoneBg = new DeviceRgb(230, 230, 230); // légèrement élevé
            else                 zoneBg = new DeviceRgb(245, 245, 245); // normal

            Cell col = nb(1).setTextAlignment(TextAlignment.CENTER)
                    .setBorder(new SolidBorder(LIGHT_GRAY, 0.2f))
                    .setBackgroundColor(zoneBg);

            // Espace au-dessus du point
            for (int r = 0; r < rowsAbove; r++)
                col.add(p(" ", regular, 5));

            // Le point avec sa valeur
            col.add(p("●", bold, 11).setFontColor(DARK));
            col.add(p(fmt3(vals[i]), bold, 6.5f));

            // Espace en dessous du point
            for (int r = 0; r < rowsBelow; r++)
                col.add(p(" ", regular, 5));

            // Label segment en bas
            col.add(new LineSeparator(new SolidLine(0.2f)));
            col.add(p(segs[i], regular, 5).setFontColor(MID_GRAY));
            plot.addCell(col);
        }
        chart.addCell(nb(0).add(plot));
        s.addCell(nb(0).add(chart));
        return s;
    }

    /**
     * "Historique" page 2 — Poids, ECT, EIC, EEC, Ratio EEC
     */
    private Table secHistoriquePage2(InBodyMeasurement m, List<InBodyReportSummary> history,
                                     PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Historique", bold));

        int maxH  = Math.min(history.size(), 5);
        List<InBodyReportSummary> items = history.isEmpty() ? List.of() : history.subList(0, maxH);
        int nCols = Math.max(items.size(), 1);

        float[] widths = new float[2 + nCols];
        widths[0] = 22f;
        for (int i = 1; i <= nCols; i++) widths[i] = 56f / nCols;
        widths[nCols + 1] = 22f;

        Table t = new Table(UnitValue.createPercentArray(widths))
                .setWidth(UnitValue.createPercentValue(100));

        histRow(t, "Poids",  "(kg)",     items, r -> fmt(r.getWeight()),           fmt(m.getWeight()),            bold, regular);
        histRow(t, "ECT",    "(L)\nEau corporelle totale",  items, r -> "-", fmt(m.getTotalBodyWater()),    bold, regular);
        histRow(t, "EIC",    "(L)\nEau intracellulaire",    items, r -> "-", fmt(m.getIntracellularWater()), bold, regular);
        histRow(t, "EEC",    "(L)\nEau extracellulaire",    items, r -> "-", fmt(m.getExtracellularWater()), bold, regular);
        histRow(t, "Ratio EEC", "",      items, r -> "-",                           fmt3(m.getEcwTbw()),           bold, regular);

        // Ligne dates
        t.addCell(nb(1).add(p("● Récent  ☐ Total", regular, 5).setFontColor(MID_GRAY)));
        if (items.isEmpty()) {
            t.addCell(nb(0).setTextAlignment(TextAlignment.CENTER).add(
                    p(m.getTestDateTime() != null ? m.getTestDateTime().format(DT_FMT) : "-",
                            regular, 5).setFontColor(MID_GRAY)));
        } else {
            for (InBodyReportSummary it : items) {
                String ds = it.getTestDateTime() != null
                        ? it.getTestDateTime().format(SHORT_FMT2) : "-";
                t.addCell(nb(0).setTextAlignment(TextAlignment.CENTER)
                        .add(p(ds, regular, 5).setFontColor(MID_GRAY)));
            }
        }
        t.addCell(nb(1));
        s.addCell(nb(0).add(t));
        return s;
    }

