    private Table secCourbeTendance(InBodyMeasurement m, List<InBodyReportSummary> history,
                                    PdfFont bold, PdfFont regular, PdfDocument pdf) {
        Table s = wrap();
        s.addCell(secTitleCell("Courbes de tendance — Évolution temporelle", bold));

        int n = history.size();
        if (n < 2) {
            s.addCell(nb(4).add(p("Historique insuffisant (min. 2 mesures).", regular, 7).setFontColor(MID_GRAY)));
            return s;
        }

        double[] weights = history.stream().mapToDouble(r -> r.getWeight() != null ? r.getWeight() : 0).toArray();
        double[] smms    = history.stream().mapToDouble(r -> r.getSkeletalMuscleMass() != null ? r.getSkeletalMuscleMass() : 0).toArray();
        double[] fats    = history.stream().mapToDouble(r -> r.getPercentBodyFat() != null ? r.getPercentBodyFat() : 0).toArray();

        // Légende
        Table legend = new Table(UnitValue.createPercentArray(new float[]{33, 33, 34})).setWidth(UnitValue.createPercentValue(100));
        legend.addCell(nb(1).add(new Paragraph()
                .add(new Text("━━  ").setFont(bold).setFontSize(8).setFontColor(new DeviceRgb(60,60,60)))
                .add(new Text("Poids (kg)").setFont(regular).setFontSize(6)).setMargin(0)));
        legend.addCell(nb(1).add(new Paragraph()
                .add(new Text("━━  ").setFont(bold).setFontSize(8).setFontColor(new DeviceRgb(100,100,100)))
                .add(new Text("MMS (kg)").setFont(regular).setFontSize(6)).setMargin(0)));
        legend.addCell(nb(1).add(new Paragraph()
                .add(new Text("━━  ").setFont(bold).setFontSize(8).setFontColor(new DeviceRgb(150,150,150)))
                .add(new Text("TGC (%)").setFont(regular).setFontSize(6)).setMargin(0)));
        s.addCell(nb(1).add(legend));

        // Barres grouped
        int BAR_H = 80;
        double wMin = minOf(weights) - 2, wMax = maxOf(weights) + 2;
        double sMin = minOf(smms) - 1,    sMax = maxOf(smms) + 1;
        double fMin = minOf(fats) - 2,    fMax = maxOf(fats) + 2;
        if (wMax == wMin) { wMin -= 5; wMax += 5; }
        if (sMax == sMin) { sMin -= 2; sMax += 2; }
        if (fMax == fMin) { fMin -= 5; fMax += 5; }

        float[] eq = new float[n]; java.util.Arrays.fill(eq, 1f);
        Table chart = new Table(UnitValue.createPercentArray(eq)).setWidth(UnitValue.createPercentValue(100))
                .setBorder(new SolidBorder(LIGHT_GRAY, 0.5f)).setBackgroundColor(VLIGHT_GRAY);

        for (int i = 0; i < n; i++) {
            InBodyReportSummary r = history.get(i);
            float wH  = Math.max(4, (float)((weights[i] - wMin) / (wMax - wMin) * BAR_H));
            float smH = Math.max(4, (float)((smms[i]    - sMin) / (sMax - sMin) * BAR_H));
            float fgH = Math.max(4, (float)((fats[i]    - fMin) / (fMax - fMin) * BAR_H));

            Cell col = new Cell().setBorder(new SolidBorder(LIGHT_GRAY, 0.2f))
                    .setPadding(1).setBackgroundColor(VLIGHT_GRAY).setTextAlignment(TextAlignment.CENTER);

            float bw = 100f / 3f;
            Table bars = new Table(UnitValue.createPercentArray(new float[]{bw, bw, bw})).setWidth(UnitValue.createPercentValue(100));
            bars.addCell(new Cell().setBorder(Border.NO_BORDER)
                    .add(new Table(UnitValue.createPercentArray(new float[]{100})).setWidth(UnitValue.createPercentValue(100))
                            .addCell(new Cell().setHeight(BAR_H - wH).setBackgroundColor(VLIGHT_GRAY).setBorder(Border.NO_BORDER))
                            .addCell(new Cell().setHeight(wH).setBackgroundColor(new DeviceRgb(60, 60, 60)).setBorder(Border.NO_BORDER))));
            bars.addCell(new Cell().setBorder(Border.NO_BORDER)
                    .add(new Table(UnitValue.createPercentArray(new float[]{100})).setWidth(UnitValue.createPercentValue(100))
                            .addCell(new Cell().setHeight(BAR_H - smH).setBackgroundColor(VLIGHT_GRAY).setBorder(Border.NO_BORDER))
                            .addCell(new Cell().setHeight(smH).setBackgroundColor(new DeviceRgb(100, 100, 100)).setBorder(Border.NO_BORDER))));
            bars.addCell(new Cell().setBorder(Border.NO_BORDER)
                    .add(new Table(UnitValue.createPercentArray(new float[]{100})).setWidth(UnitValue.createPercentValue(100))
                            .addCell(new Cell().setHeight(BAR_H - fgH).setBackgroundColor(VLIGHT_GRAY).setBorder(Border.NO_BORDER))
                            .addCell(new Cell().setHeight(fgH).setBackgroundColor(new DeviceRgb(150, 150, 150)).setBorder(Border.NO_BORDER))));

            col.add(bars);
            col.add(p(fmt(weights[i]), regular, 4.5f).setFontColor(new DeviceRgb(60,60,60)));
            col.add(p(fmt(smms[i]),    regular, 4.5f).setFontColor(new DeviceRgb(100,100,100)));
            col.add(p(fmt(fats[i]) + "%", regular, 4.5f).setFontColor(new DeviceRgb(150,150,150)));
            String ds = r.getTestDateTime() != null ? r.getTestDateTime().format(SHORT_FMT) : "-";
            col.add(p(ds, regular, 4).setFontColor(MID_GRAY));
            chart.addCell(col);
        }
        s.addCell(nb(1).add(chart));

        // Indicateurs de tendance
        if (n >= 2) {
            double dW = weights[n-1] - weights[0];
            double dS = smms[n-1] - smms[0];
            double dF = fats[n-1] - fats[0];
            Table trend = new Table(UnitValue.createPercentArray(new float[]{33, 33, 34})).setWidth(UnitValue.createPercentValue(100));
            trend.addCell(nb(1).add(p((dW > 0.5 ? "↑ +" : dW < -0.5 ? "↓ " : "→ ") + fmt(Math.abs(dW)) + " kg", bold, 6)));
            trend.addCell(nb(1).add(p((dS > 0.3 ? "↑ +" : dS < -0.3 ? "↓ " : "→ ") + fmt(Math.abs(dS)) + " kg", bold, 6)));
            trend.addCell(nb(1).add(p((dF > 0.5 ? "↑ +" : dF < -0.5 ? "↓ " : "→ ") + fmt(Math.abs(dF)) + "%", bold, 6)));
            s.addCell(nb(1).add(trend));
        }
        return s;
    }

    private Table secRadarChart(InBodyMeasurement m, PdfFont bold, PdfFont regular, PdfDocument pdf) {
        Table s = wrap();
        s.addCell(secTitleCell("Profil biométrique — Radar normalisé (0–100)", bold));
        Cell cc = nb(3).setBackgroundColor(VLIGHT_GRAY).setBorder(new SolidBorder(LIGHT_GRAY, 0.5f));

        double[] axes = {
                clamp01(m.getInbodyScore(), 0, 100),
                clamp01(m.getSkeletalMuscleMass(), m.getSmmLowerLimit(), m.getSmmUpperLimit()),
                1.0 - clamp01(m.getPercentBodyFat(), m.getPbfLowerLimit(), m.getPbfUpperLimit()),
                1.0 - clamp01(m.getBmi(), m.getBmiLowerLimit(), m.getBmiUpperLimit()),
                clamp01(m.getEcwTbw(), 0.32, 0.39),
                clamp01(m.getV50khzWholeBodyPhaseAngle(), 3.0, 8.0)
        };
        String[] labels = {"Score", "MMS", "Graisse(inv.)", "IMC(inv.)", "Hydrat.", "Phase"};
        String[] values = {
                fmt(m.getInbodyScore()),
                fmt(m.getSkeletalMuscleMass()) + " kg",
                fmt(m.getPercentBodyFat()) + "%",
                fmt(m.getBmi()),
                fmt3(m.getEcwTbw()),
                fmt(m.getV50khzWholeBodyPhaseAngle()) + "°"
        };

        try {
            float size = 110f;
            PdfFormXObject xobj = new PdfFormXObject(new Rectangle(size, size));
            PdfCanvas pc = new PdfCanvas(xobj, pdf);
            float cx = size / 2f, cy = size / 2f, maxR = size / 2f - 14f;

            // Anneaux concentriques
            for (float ring : new float[]{1f, 0.66f, 0.33f}) {
                pc.setFillColor(ring > 0.66f ? new DeviceRgb(230,230,230)
                        : ring > 0.33f ? new DeviceRgb(215,215,215)
                        : new DeviceRgb(200,200,200));
                pc.setStrokeColor(LIGHT_GRAY);
                pc.setLineWidth(0.3f);
                float r = maxR * ring;
                pc.moveTo(cx + r * Math.cos(Math.PI/2), cy + r * Math.sin(Math.PI/2));
                for (int i = 1; i <= 6; i++) {
                    double angle = Math.PI/2 + i * 2 * Math.PI / 6;
                    pc.lineTo(cx + r * Math.cos(angle), cy + r * Math.sin(angle));
                }
                pc.fillStroke();
            }

            // Rayons
            pc.setStrokeColor(LIGHT_GRAY); pc.setLineWidth(0.3f);
            for (int i = 0; i < 6; i++) {
                double angle = Math.PI/2 + i * 2 * Math.PI / 6;
                pc.moveTo(cx, cy);
                pc.lineTo(cx + maxR * Math.cos(angle), cy + maxR * Math.sin(angle));
                pc.stroke();
            }

            // Polygone données
            pc.setFillColor(new DeviceRgb(150, 150, 150));
            pc.setStrokeColor(DARK); pc.setLineWidth(1.5f);
            for (int i = 0; i < 6; i++) {
                double angle = Math.PI/2 + i * 2 * Math.PI / 6;
                float r = (float)(axes[i] * maxR);
                if (i == 0) pc.moveTo(cx + r * Math.cos(angle), cy + r * Math.sin(angle));
                else        pc.lineTo(cx + r * Math.cos(angle), cy + r * Math.sin(angle));
            }
            pc.closePath(); pc.fillStroke();

            // Points
            pc.setFillColor(DARK);
            for (int i = 0; i < 6; i++) {
                double angle = Math.PI/2 + i * 2 * Math.PI / 6;
                float r = (float)(axes[i] * maxR);
                pc.circle(cx + r * Math.cos(angle), cy + r * Math.sin(angle), 2.5f);
                pc.fill();
            }

            // Labels axes
            PdfFont f = PdfFontFactory.createFont(StandardFonts.HELVETICA);
            pc.setFillColor(DARK_GRAY);
            for (int i = 0; i < 6; i++) {
                double angle = Math.PI/2 + i * 2 * Math.PI / 6;
                float lr = maxR + 10f;
                pc.beginText(); pc.setFontAndSize(f, 5f);
                pc.moveText(cx + lr * Math.cos(angle) - 8, cy + lr * Math.sin(angle) - 3);
                pc.showText(labels[i]); pc.endText();
            }
            pc.release();

            com.itextpdf.layout.element.Image img = new com.itextpdf.layout.element.Image(xobj)
                    .setWidth(size).setHeight(size);
            cc.add(img);
        } catch (Exception e) {
            log.warn("Radar chart error: {}", e.getMessage());
        }

        // Tableau des valeurs
        Table vt = new Table(UnitValue.createPercentArray(new float[]{50, 25, 25}))
                .setWidth(UnitValue.createPercentValue(100)).setMarginTop(3);
        vt.addCell(hdrCell("Indicateur", regular));
        vt.addCell(hdrCell("Valeur", regular));
        vt.addCell(hdrCell("Norme", regular));
        String[] names = {"Score InBody", "MMS", "TGC", "IMC", "ECW/TBW", "Angle phase"};
        String[] norms = {"60–80",
                fmt(m.getSmmLowerLimit()) + "–" + fmt(m.getSmmUpperLimit()),
                fmt(m.getPbfLowerLimit()) + "–" + fmt(m.getPbfUpperLimit()),
                fmt(m.getBmiLowerLimit()) + "–" + fmt(m.getBmiUpperLimit()),
                "0,32–0,39", "3,5–7,0°"};
        for (int i = 0; i < 6; i++) {
            DeviceRgb bg = i % 2 == 0 ? STRIPE_A : STRIPE_B;
            vt.addCell(new Cell().setBackgroundColor(bg).setBorder(Border.NO_BORDER).setPadding(2).add(p(names[i], regular, 6)));
            vt.addCell(new Cell().setBackgroundColor(bg).setBorder(Border.NO_BORDER).setPadding(2).setTextAlignment(TextAlignment.CENTER).add(p(values[i], bold, 6)));
            vt.addCell(new Cell().setBackgroundColor(bg).setBorder(Border.NO_BORDER).setPadding(2).setTextAlignment(TextAlignment.CENTER).add(p(norms[i], regular, 5).setFontColor(MID_GRAY)));
        }
        cc.add(vt);
        s.addCell(cc);
        return s;
    }

    private Table secDonutComposition(InBodyMeasurement m, PdfFont bold, PdfFont regular, PdfDocument pdf) {
        Table s = wrap();
        s.addCell(secTitleCell("Répartition de la composition corporelle", bold));
        Cell cc = nb(3);

        double total = safeD(m.getWeight()); if (total <= 0) total = 1;
        double water = safeD(m.getTotalBodyWater());
        double prot  = safeD(m.getProtein());
        double miner = safeD(m.getMinerals());
        double fat   = safeD(m.getBodyFatMass());
        double other = Math.max(0, total - water - prot - miner - fat);
        double[] kgs  = {water, prot, miner, fat, other};
        float[] props = new float[5];
        for (int i = 0; i < 5; i++) props[i] = (float)(kgs[i] / total * 100);
        DeviceRgb[] colors = {
                new DeviceRgb(60, 60, 60),
                new DeviceRgb(100, 100, 100),
                new DeviceRgb(140, 140, 140),
                new DeviceRgb(180, 180, 180),
                new DeviceRgb(210, 210, 210)
        };
        String[] lbls = {"Eau", "Protéines", "Minéraux", "Graisse", "Autre"};

        try {
            float ps = 90f;
            PdfFormXObject pie = new PdfFormXObject(new Rectangle(ps, ps));
            PdfCanvas pc = new PdfCanvas(pie, pdf);
            float cx = ps/2f, cy = ps/2f, r = ps/2f - 4f;
            double startA = Math.PI / 2;
            for (int i = 0; i < 5; i++) {
                double sweep = props[i] / 100.0 * 2 * Math.PI;
                double endA  = startA - sweep;
                pc.setFillColor(colors[i]); pc.setStrokeColor(WHITE); pc.setLineWidth(0.8f);
                pc.moveTo(cx, cy);
                int segs = Math.max(1, (int)(sweep / (Math.PI/4)) + 1);
                double ss = sweep / segs;
                for (int sg = 0; sg < segs; sg++) {
                    double a0 = startA - sg * ss, a1 = a0 - ss;
                    double k = 4.0/3.0 * Math.tan(ss / 4.0);
                    pc.curveTo(cx + r*Math.cos(a0) - k*r*Math.sin(a0), cy + r*Math.sin(a0) + k*r*Math.cos(a0),
                            cx + r*Math.cos(a1) + k*r*Math.sin(a1), cy + r*Math.sin(a1) - k*r*Math.cos(a1),
                            cx + r*Math.cos(a1), cy + r*Math.sin(a1));
                }
                pc.closePath(); pc.fillStroke();
                startA = endA;
            }
            pc.release();

            Table row = new Table(UnitValue.createPercentArray(new float[]{ps + 8, 100})).setWidth(UnitValue.createPercentValue(100));
            row.addCell(nb(1).add(new com.itextpdf.layout.element.Image(pie).setWidth(ps).setHeight(ps)));
            Table leg = new Table(UnitValue.createPercentArray(new float[]{12, 55, 33})).setWidth(UnitValue.createPercentValue(100));
            leg.addCell(hdrCell("", regular)); leg.addCell(hdrCell("Composant", regular)); leg.addCell(hdrCell("kg (%)", regular));
            for (int i = 0; i < 5; i++) {
                leg.addCell(new Cell().setBackgroundColor(colors[i]).setHeight(10).setBorder(Border.NO_BORDER));
                leg.addCell(nb(1).add(p(lbls[i], regular, 7)));
                leg.addCell(nb(1).setTextAlignment(TextAlignment.RIGHT)
                        .add(p(fmt(kgs[i]) + " (" + fmt((double)props[i]) + "%)", bold, 6.5f)));
            }
            row.addCell(nb(1).add(leg));
            cc.add(row);
        } catch (Exception e) { log.warn("Pie chart error: {}", e.getMessage()); }

        cc.add(p("Poids : " + fmt(m.getWeight()) + " kg  |  Masse maigre : " +
                        fmt(m.getFatFreeMass()) + " kg  |  TGC : " + fmt(m.getPercentBodyFat()) + "%",
                bold, 6.5f).setFontColor(DARK_GRAY));
        s.addCell(cc);
        return s;
    }

    private Table secEquilibreSegmentaire(InBodyMeasurement m, PdfFont bold, PdfFont regular, PdfDocument pdf) {
        Table s = wrap();
        s.addCell(secTitleCell("Équilibre segmentaire gauche / droite", bold));
        Cell cc = nb(3);
        Table t = new Table(UnitValue.createPercentArray(new float[]{22, 36, 6, 36}))
                .setWidth(UnitValue.createPercentValue(100));
        t.addCell(hdrCell("Segment", regular));
        t.addCell(hdrCell("← Gauche", regular));
        t.addCell(hdrCell("", regular));
        t.addCell(hdrCell("Droite →", regular));
        symRow(t, "Bras — Masse Maigre",  m.getFfmLeftArm(),      m.getFfmRightArm(),      regular, bold);
        symRow(t, "Bras — Eau (L)",       m.getTbwLeftArm(),      m.getTbwRightArm(),      regular, bold);
        symRow(t, "Jambe — Masse Maigre", m.getFfmLeftLeg(),      m.getFfmRightLeg(),      regular, bold);
        symRow(t, "Jambe — Eau (L)",      m.getTbwLeftLeg(),      m.getTbwRightLeg(),      regular, bold);
        symRow(t, "Bras — Ratio EEC",     m.getEcwTbwOfLeftArm(), m.getEcwTbwOfRightArm(), regular, bold);
        symRow(t, "Jambe — Ratio EEC",    m.getEcwTbwOfLeftLeg(), m.getEcwTbwOfRightLeg(), regular, bold);
        cc.add(t);
        cc.add(p("Note : asymétrie > 5% mérite une attention clinique.", regular, 5.5f).setFontColor(MID_GRAY));
        s.addCell(cc);
        return s;
    }

    private void symRow(Table t, String label, Double left, Double right, PdfFont regular, PdfFont bold) {
        double l = safeD(left), r = safeD(right), total = l + r;
        float lPct = total > 0 ? (float)(l / total * 100) : 50f;
        float diff = Math.abs(lPct - 50f);
        DeviceRgb bc = diff < 3 ? new DeviceRgb(80,80,80) : diff < 8 ? new DeviceRgb(130,130,130) : LIGHT_GRAY;

        t.addCell(nb(1).add(p(label, regular, 6)));
        float lf = Math.max(1, lPct), le = Math.max(1, 100 - lPct);
        Table lb = new Table(UnitValue.createPercentArray(new float[]{le, lf})).setWidth(UnitValue.createPercentValue(100));
        lb.addCell(new Cell().setHeight(7).setBackgroundColor(BAR_BG).setBorder(Border.NO_BORDER));
        lb.addCell(new Cell().setHeight(7).setBackgroundColor(bc).setBorder(Border.NO_BORDER));
        Cell lc = nb(1).add(lb); lc.add(p(fmt(left), bold, 5.5f).setTextAlignment(TextAlignment.RIGHT));
        t.addCell(lc);
        t.addCell(nb(0).setTextAlignment(TextAlignment.CENTER)
                .add(p(diff < 2 ? "=" : "≠", bold, 7).setFontColor(diff < 2 ? DARK : MID_GRAY)));
        float rf = Math.max(1, 100 - lPct), re = Math.max(1, lPct);
        Table rb = new Table(UnitValue.createPercentArray(new float[]{rf, re})).setWidth(UnitValue.createPercentValue(100));
        rb.addCell(new Cell().setHeight(7).setBackgroundColor(bc).setBorder(Border.NO_BORDER));
        rb.addCell(new Cell().setHeight(7).setBackgroundColor(BAR_BG).setBorder(Border.NO_BORDER));
        Cell rc = nb(1).add(rb); rc.add(p(fmt(right), bold, 5.5f));
        t.addCell(rc);
    }

    private Table secInterpretationClinique(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Interprétation clinique automatisée", bold));
        Cell cc = nb(4).setBackgroundColor(VLIGHT_GRAY);
        Table t = twoCol(50, 50);
        Cell lc = nb(3), rc = nb(3);

        Double bmi = m.getBmi();
        String imcCat = bmi == null ? "N/D"
                : bmi < 18.5 ? "Insuffisance pondérale" : bmi < 25 ? "Poids normal"
                : bmi < 30   ? "Surpoids" : bmi < 35 ? "Obésité classe I"
                : bmi < 40   ? "Obésité classe II" : "Obésité classe III";

        Double vfa = m.getVfaVisceralFatArea();
        String vfaRisk = vfa == null ? "-" : vfa < 100 ? "Risque faible" : vfa < 160 ? "Risque modéré" : "Risque élevé";

        Double smm = m.getSkeletalMuscleMass();
        String smmStat = smm == null ? "-"
                : (m.getSmmLowerLimit() != null && smm < m.getSmmLowerLimit()) ? "Insuffisante"
                : (m.getSmmUpperLimit() != null && smm > m.getSmmUpperLimit()) ? "Élevée" : "Normale";

        Double ecw = m.getEcwTbw();
        String ecwStat = ecw == null ? "-"
                : ecw < 0.36 ? "Hydratation basse"
                : ecw > 0.40 ? "Rétention possible"
                : "Équilibre normal";

        lc.add(p("Statut pondéral :", bold, 7)); lc.add(p(imcCat, bold, 8)); lc.add(spacer(3));
        lc.add(p("Masse musculaire :", bold, 7)); lc.add(p(smmStat, bold, 8)); lc.add(spacer(3));
        lc.add(p("Score InBody :", bold, 7));
        lc.add(p(fmt(m.getInbodyScore()) + " / 100 — " + scoreLabel(m.getInbodyScore()), bold, 8));

        rc.add(p("Graisse viscérale :", bold, 7)); rc.add(p(vfaRisk + " (" + fmt(vfa) + " cm²)", bold, 8)); rc.add(spacer(3));
        rc.add(p("Équilibre hydrique :", bold, 7)); rc.add(p(ecwStat + " (" + fmt3(ecw) + ")", bold, 8)); rc.add(spacer(3));
        rc.add(p("Angle de phase :", bold, 7));
        rc.add(p(fmt(m.getV50khzWholeBodyPhaseAngle()) + "° — " + phaseLabel(m.getV50khzWholeBodyPhaseAngle()), bold, 8));

        t.addCell(lc); t.addCell(rc);
        cc.add(t);
        s.addCell(cc);
        return s;
    }

    private Table secRecommandationsEnrichies(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
