        Table t = new Table(UnitValue.createPercentArray(new float[]{33, 33, 34}))
                .setWidth(UnitValue.createPercentValue(100));

        // Col 1 : poids
        Cell c1 = new Cell().setBackgroundColor(VLIGHT_GRAY)
                .setBorder(new SolidBorder(LIGHT_GRAY, 0.5f)).setPadding(5);
        c1.add(p("Objectifs pondéraux", bold, 7.5f));
        c1.add(spacer(3));
        c1.add(p("Poids cible : " + fmt(m.getTargetWeight()) + " kg", regular, 7));
        c1.add(p("Poids actuel : " + fmt(m.getWeight()) + " kg", regular, 7));
        double diff = safeD(m.getWeight()) - safeD(m.getTargetWeight());
        c1.add(p("Différence : " + (diff > 0 ? "-" : "+") + fmt(Math.abs(diff)) + " kg", bold, 7));
        c1.add(spacer(3));
        c1.add(p("Contrôle masse grasse : " + fmt(m.getBfmControl()) + " kg", regular, 6.5f));
        c1.add(p("Contrôle masse maigre : " + fmt(m.getFfmControl()) + " kg", regular, 6.5f));
        t.addCell(c1);

        // Col 2 : énergie
        Cell c2 = new Cell().setBackgroundColor(VLIGHT_GRAY)
                .setBorder(new SolidBorder(LIGHT_GRAY, 0.5f)).setPadding(5);
        c2.add(p("Bilan énergétique", bold, 7.5f));
        c2.add(spacer(3));
        c2.add(p("Métabolisme de base :", regular, 7));
        c2.add(p(fmt(m.getBmrBasalMetabolicRate()) + " kcal/jour", bold, 8));
        c2.add(spacer(3));
        c2.add(p("Apport recommandé :", regular, 7));
        c2.add(p(fmt(m.getRecommendedCalorieIntake()) + " kcal/jour", bold, 8));
        c2.add(spacer(3));
        c2.add(p("Norme : " + range(m.getLowerLimitBmrNormalRange(), m.getUpperLimitBmrNormalRange()) + " kcal",
                regular, 6).setFontColor(MID_GRAY));
        t.addCell(c2);

        // Col 3 : conseils
        Cell c3 = new Cell().setBackgroundColor(VLIGHT_GRAY)
                .setBorder(new SolidBorder(LIGHT_GRAY, 0.5f)).setPadding(5);
        c3.add(p("Conseils généraux", bold, 7.5f));
        c3.add(spacer(3));
        if (m.getPercentBodyFat() != null && m.getPbfUpperLimit() != null
                && m.getPercentBodyFat() > m.getPbfUpperLimit())
            c3.add(bullet("Réduire les graisses saturées.", regular));
        if (m.getSkeletalMuscleMass() != null && m.getSmmLowerLimit() != null
                && m.getSkeletalMuscleMass() < m.getSmmLowerLimit())
            c3.add(bullet("Augmenter la résistance musculaire.", regular));
        if (m.getVfaVisceralFatArea() != null && m.getVfaVisceralFatArea() > 100)
            c3.add(bullet("Exercice cardio 150 min/semaine.", regular));
        if (safeD(m.getEcwTbw()) > 0.40)
            c3.add(bullet("Surveiller la rétention hydrique.", regular));
        c3.add(bullet("Maintenir un suivi trimestriel.", regular));
        c3.add(bullet("Boire 1,5–2 L d'eau par jour.", regular));
        t.addCell(c3);

        s.addCell(nb(0).add(t));
        return s;
    }

    // ══════════════════════════════════════════════════════════════════════════
    // PRIMITIVES GRAPHIQUES
    // ══════════════════════════════════════════════════════════════════════════

    /**
     * Barre colorée universelle (reproduit exactement la barre originale) :
     *  - Graduation numérique sur le dessus
     *  - 3 zones : Inférieur | Normal | Supérieur
     *  - Marqueur ▼ à la position de la valeur
     *  - Valeur numérique centrée sous le marqueur
     */
    private Table buildColorBar(Double value, Double lo, Double hi,
                                double sMin, double sMax,
                                int steps, PdfFont regular) {
        Table wrap = new Table(UnitValue.createPercentArray(new float[]{100}))
                .setWidth(UnitValue.createPercentValue(100));
        try {
            double range  = sMax - sMin; if (range <= 0) range = 1;
            double loSafe = lo != null ? lo : sMin + range * 0.3;
            double hiSafe = hi != null ? hi : sMin + range * 0.7;

            // Graduation
            Table scale = new Table(UnitValue.createPercentArray(new float[steps + 1])).setWidth(UnitValue.createPercentValue(100));
            double step = range / steps;
            for (int i = 0; i <= steps; i++) {
                double tv = sMin + i * step;
                String ts = fmtScaleTick(tv);
                scale.addCell(new Cell().setBorder(Border.NO_BORDER).setPadding(0)
                        .setTextAlignment(i == 0 ? TextAlignment.LEFT
                                : i == steps ? TextAlignment.RIGHT : TextAlignment.CENTER)
                        .add(p(ts, regular, 5).setFontColor(MID_GRAY)));
            }
            wrap.addCell(nb(0).add(scale));

            // Calcul positions %
            float loP  = clampPct((loSafe - sMin) / range * 100);
            float hiP  = clampPct((hiSafe - sMin) / range * 100);
            float valP = value != null ? clampPct((value - sMin) / range * 100) : 50f;

            float s1 = Math.max(0.5f, loP);
            float s2 = Math.max(0.5f, hiP - loP);
            float s3 = Math.max(0.5f, 100f - hiP);

            // Barre 3 zones colorées : rouge (inférieur) | bleu (normal) | vert (supérieur)
            Table bar = new Table(UnitValue.createPercentArray(new float[]{s1, s2, s3})).setWidth(UnitValue.createPercentValue(100));
            bar.addCell(new Cell().setHeight(7).setBackgroundColor(ZONE_LOW).setBorder(Border.NO_BORDER));
            bar.addCell(new Cell().setHeight(7).setBackgroundColor(ZONE_NORMAL).setBorder(Border.NO_BORDER));
            bar.addCell(new Cell().setHeight(7).setBackgroundColor(ZONE_HIGH).setBorder(Border.NO_BORDER));
            wrap.addCell(nb(0).add(bar));

            // Marqueur ▼ coloré selon la zone (rouge=bas, bleu=normal, vert=haut)
            DeviceRgb markerColor = (value != null && value < loSafe) ? FILL_LOW
                    : (value != null && value > hiSafe) ? FILL_HIGH : FILL_NORMAL;
            float ml = Math.max(0f, valP - 3f);
            float mr = Math.max(0.5f, 100f - valP - 3f);
            Table mk = new Table(UnitValue.createPercentArray(new float[]{ml, 6, mr})).setWidth(UnitValue.createPercentValue(100));
            mk.addCell(nb(0));
            mk.addCell(nb(0).setTextAlignment(TextAlignment.CENTER)
                    .add(p("▼", regular, 7).setFontColor(markerColor)));
            mk.addCell(nb(0));
            wrap.addCell(nb(0).add(mk));

            // Valeur sous le marqueur (même couleur que le marqueur)
            wrap.addCell(nb(0).setTextAlignment(TextAlignment.CENTER)
                    .add(p(fmt(value), regular, 6).setFontColor(markerColor)));

        } catch (Exception e) {
            log.warn("colorBar error: {}", e.getMessage());
        }
        return wrap;
    }

    /**
     * Barre de pourcentage segmentaire (80–120%)
     * Zones : <90% | 90–110% | >110%
     */
    private Table buildPercentBar(Double pct, double pctMin, double pctMax, PdfFont regular) {
        Table wrap = new Table(UnitValue.createPercentArray(new float[]{100}))
                .setWidth(UnitValue.createPercentValue(100));
        // Graduation
        Table scale = new Table(UnitValue.createPercentArray(new float[]{20, 20, 20, 20, 20})).setWidth(UnitValue.createPercentValue(100));
        for (String tick : new String[]{"80", "90", "100", "110", "120"})
            scale.addCell(nb(0).setTextAlignment(TextAlignment.CENTER)
                    .add(p(tick, regular, 5).setFontColor(MID_GRAY)));
        wrap.addCell(nb(0).add(scale));

        // Barre zones colorées : rouge | bleu | vert
        Table bar = new Table(UnitValue.createPercentArray(new float[]{20, 60, 20})).setWidth(UnitValue.createPercentValue(100));
        bar.addCell(new Cell().setHeight(7).setBackgroundColor(ZONE_LOW).setBorder(Border.NO_BORDER));
        bar.addCell(new Cell().setHeight(7).setBackgroundColor(ZONE_NORMAL).setBorder(Border.NO_BORDER));
        bar.addCell(new Cell().setHeight(7).setBackgroundColor(ZONE_HIGH).setBorder(Border.NO_BORDER));
        wrap.addCell(nb(0).add(bar));

        // Marqueur coloré selon position
        double sp = pct != null ? pct : 100;
        float pos = clampPct((sp - pctMin) / (pctMax - pctMin) * 100);
        DeviceRgb pBarColor = (sp < 90) ? FILL_LOW : (sp > 110) ? FILL_HIGH : FILL_NORMAL;
        float ml = Math.max(0f, pos - 3f), mr = Math.max(0.5f, 100f - pos - 3f);
        Table mk = new Table(UnitValue.createPercentArray(new float[]{ml, 6, mr})).setWidth(UnitValue.createPercentValue(100));
        mk.addCell(nb(0));
        mk.addCell(nb(0).setTextAlignment(TextAlignment.CENTER).add(p("▼", regular, 7).setFontColor(pBarColor)));
        mk.addCell(nb(0));
        wrap.addCell(nb(0).add(mk));
        return wrap;
    }

    /**
     * CORRECTION 1 — Barre segmentaire masse maigre (large, identique à l'original).
     * Graduation sur 5 points : 80 / 90 / 100 / 110 / 120 %
     * Barre pleine noire avec zones gris clair aux extrémités.
     * Marqueur ▼ double : un pour le poids idéal (ligne de référence) et
     * un pour la valeur actuelle (position réelle).
     * La hauteur de la barre est plus grande (10px) pour ressembler aux barres
     * "très larges" de l'original.
     */
    private Table buildSegMaigreBar(Double pct, double pctMin, double pctMax, PdfFont regular) {
        Table wrap = new Table(UnitValue.createPercentArray(new float[]{100}))
                .setWidth(UnitValue.createPercentValue(100));

        // Graduation : 5 ticks de 80 à 120
        Table scale = new Table(UnitValue.createPercentArray(new float[]{20, 20, 20, 20, 20})).setWidth(UnitValue.createPercentValue(100));
        for (String tick : new String[]{"80", "90", "100", "110", "120"})
            scale.addCell(nb(0).setTextAlignment(TextAlignment.CENTER)
                    .add(p(tick, regular, 5).setFontColor(MID_GRAY)));
        wrap.addCell(nb(0).add(scale));

        // Barre haute (10px) zones colorées : rouge | bleu | vert
        Table bar = new Table(UnitValue.createPercentArray(new float[]{20, 60, 20})).setWidth(UnitValue.createPercentValue(100));
        bar.addCell(new Cell().setHeight(10).setBackgroundColor(ZONE_LOW).setBorder(Border.NO_BORDER));
        bar.addCell(new Cell().setHeight(10).setBackgroundColor(ZONE_NORMAL).setBorder(Border.NO_BORDER));
        bar.addCell(new Cell().setHeight(10).setBackgroundColor(ZONE_HIGH).setBorder(Border.NO_BORDER));
        wrap.addCell(nb(0).add(bar));

        // Marqueur ▼ coloré selon la zone
        double sp  = pct != null ? pct : 100;
        float pos  = clampPct((sp - pctMin) / (pctMax - pctMin) * 100);
        DeviceRgb segColor = (sp < 90) ? FILL_LOW : (sp > 110) ? FILL_HIGH : FILL_NORMAL;
        float ml   = Math.max(0f, pos - 3f);
        float mr   = Math.max(0.5f, 100f - pos - 3f);
        Table mk = new Table(UnitValue.createPercentArray(new float[]{ml, 6, mr})).setWidth(UnitValue.createPercentValue(100));
        mk.addCell(nb(0));
        mk.addCell(nb(0).setTextAlignment(TextAlignment.CENTER).add(p("▼", regular, 8).setFontColor(segColor)));
        mk.addCell(nb(0));
        wrap.addCell(nb(0).add(mk));
        return wrap;
    }

    // ══════════════════════════════════════════════════════════════════════════
    // UTILITAIRES DE MISE EN PAGE
    // ══════════════════════════════════════════════════════════════════════════

    private Table twoCol(float l, float r) {
        return new Table(UnitValue.createPercentArray(new float[]{l, r}))
                .setWidth(UnitValue.createPercentValue(100)).setMarginTop(1);
    }

    private Table wrap() {
        return new Table(UnitValue.createPercentArray(new float[]{100}))
                .setWidth(UnitValue.createPercentValue(100))
                .setMarginBottom(3)
                .setBorder(new SolidBorder(LIGHT_GRAY, 0.4f));
    }

    private Table resumeTable() {
        return new Table(UnitValue.createPercentArray(new float[]{50, 25, 25}))
                .setWidth(UnitValue.createPercentValue(100));
    }

    private Cell secTitleCell(String text, PdfFont bold) {
        return new Cell()
                .setBackgroundColor(new DeviceRgb(50, 110, 185))   // bleu InBody
                .setBorder(Border.NO_BORDER)
                .setBorderBottom(new SolidBorder(new DeviceRgb(30, 80, 150), 0.8f))
                .setPadding(3)
                .add(new Paragraph(text).setFont(bold).setFontSize(7.5f)
                        .setFontColor(WHITE).setMargin(0));
    }

    private Cell hdrCell(String text, PdfFont regular) {
        return new Cell().setBackgroundColor(HDR_BG)
                .setBorder(new SolidBorder(new DeviceRgb(180, 210, 235), 0.3f)).setPadding(1)
                .setTextAlignment(TextAlignment.CENTER)
                .add(p(text, regular, 5.5f).setFontColor(new DeviceRgb(50, 90, 150)));
    }

    private Cell nb()      { return new Cell().setBorder(Border.NO_BORDER); }
    private Cell nb(int p) { return new Cell().setBorder(Border.NO_BORDER).setPadding(p); }

    private Paragraph p(String text, PdfFont font, float size) {
        return new Paragraph(text).setFont(font).setFontSize(size).setMargin(0);
    }

    private Paragraph spacer(float h) {
        return new Paragraph(" ").setFontSize(1).setMarginTop(h / 2).setMarginBottom(h / 2);
    }

    private Paragraph bullet(String text, PdfFont regular) {
        return new Paragraph("• " + text).setFont(regular).setFontSize(6.5f).setMargin(0).setMarginTop(2);
    }

    // ══════════════════════════════════════════════════════════════════════════
    // FORMATTERS
    // ══════════════════════════════════════════════════════════════════════════

    private String fmt(Double v) {
        if (v == null) return "-";
        if (v == Math.floor(v) && !Double.isInfinite(v)) return String.valueOf(v.intValue());
        return String.format("%.1f", v);
    }

    private String fmt(Integer v) { return v != null ? String.valueOf(v) : "-"; }

    private String fmt3(Double v) { return v == null ? "-" : String.format("%.3f", v); }

    private String fmtPct(Double v) { return v == null ? "-" : fmt(v); }

    private String fmtScaleTick(double tv) {
        if (tv == Math.floor(tv) && !Double.isInfinite(tv)) return String.valueOf((int) tv);
        return String.format("%.3f", tv).replaceAll("0+$", "").replaceAll("\\.$", "");
    }

    private String range(Double lo, Double hi) {
        if (lo == null && hi == null) return "";
        return "( " + fmt(lo) + " ~ " + fmt(hi) + " )";
    }

    private String safe(String v) { return v != null ? v : "-"; }

    private double safeD(Double v) { return v != null ? v : 0.0; }

    private String fmtGender(String g) {
        if (g == null) return "-";
        return (g.equalsIgnoreCase("Female") || g.equalsIgnoreCase("F")) ? "Femme" : "Homme";
    }

    private float clampPct(double v) { return (float) Math.max(0.5, Math.min(99.5, v)); }

    private double minOf(double[] arr) { double m = Double.MAX_VALUE; for (double v : arr) if (v < m) m = v; return m; }
    private double maxOf(double[] arr) { double m = -Double.MAX_VALUE; for (double v : arr) if (v > m) m = v; return m; }

    private double clamp01(Double val, Double lo, Double hi) {
        if (val == null || lo == null || hi == null) return 0.5;
        double range = hi - lo; if (range == 0) return 0.5;
        return Math.max(0, Math.min(1, (val - lo) / range));
    }
    private double clamp01(Double val, double lo, double hi) { return clamp01(val, lo, hi); }
    private double clamp01(Integer val, int lo, int hi) {
        return clamp01(val != null ? val.doubleValue() : null, (double) lo, (double) hi);
    }

    private String scoreLabel(Integer s) {
        if (s == null) return "-";
        return s >= 90 ? "Excellent" : s >= 80 ? "Très bien" : s >= 70 ? "Bien" : s >= 60 ? "Moyen" : "À améliorer";
    }

    private String phaseLabel(Double deg) {
        if (deg == null) return "-";
        return deg >= 7 ? "Excellent" : deg >= 5 ? "Normal" : deg >= 3.5 ? "Limite basse" : "Faible";
    }
}

package com.hellcap.nutritiondoctor.domain.service;

import com.hellcap.nutritiondoctor.domain.models.InBodyMeasurement;
import com.hellcap.nutritiondoctor.domain.models.InBodyReportSummary;
import com.hellcap.nutritiondoctor.domain.port.input.InBodyPdfUseCases;
import com.hellcap.nutritiondoctor.domain.port.output.InBodyMeasurements;
import com.itextpdf.io.font.PdfEncodings;
import com.itextpdf.io.font.constants.StandardFonts;
import com.itextpdf.kernel.colors.DeviceRgb;
import com.itextpdf.kernel.font.PdfFont;
import com.itextpdf.kernel.font.PdfFontFactory;
import com.itextpdf.kernel.geom.PageSize;
import com.itextpdf.kernel.geom.Rectangle;
import com.itextpdf.kernel.pdf.PdfDocument;
import com.itextpdf.kernel.pdf.PdfWriter;
import com.itextpdf.kernel.pdf.canvas.PdfCanvas;
import com.itextpdf.kernel.pdf.canvas.draw.SolidLine;
import com.itextpdf.kernel.pdf.xobject.PdfFormXObject;
import com.itextpdf.layout.Document;
import com.itextpdf.layout.borders.Border;
import com.itextpdf.layout.borders.SolidBorder;
import com.itextpdf.layout.element.*;
import com.itextpdf.layout.properties.AreaBreakType;
import com.itextpdf.layout.properties.TextAlignment;
import com.itextpdf.layout.properties.UnitValue;
import com.itextpdf.layout.properties.VerticalAlignment;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import java.io.ByteArrayOutputStream;
import java.time.format.DateTimeFormatter;
import java.util.List;

/**
 * InBodyPdfReportService — Generates PDF reports that are 100% faithful
 * to the original InBody770 printed output (French version).
 *
 * PAGE 1  : Composition corporelle  (structure identique à l'original)
 * PAGE 2  : Eau corporelle          (structure identique à l'original)
 * PAGE 3  : Analyse & tendances     (WITH_HISTORY_AND_ANALYSIS uniquement)
 *
 * Règles structurelles STRICTES :
 *  - En-tête complet UNIQUEMENT sur la page 1
 *  - Page 2 commence par une mini-bande de continuité InBody "d'eau corporelle"
 *  - Chaque section est placée exactement à la position de l'original
 *  - Les barres colorées reproduisent les zones Inférieur/Normal/Supérieur
 *  - Le score, les graphiques SGV, la symétrie, la graisse par segment : droite p.1
 *  - La composition hydrique, eau par segment, ratios EEC, historique : gauche p.2
 *  - Les tableaux résumés : droite p.2
 */
@Service
public class InBodyPdfReportService implements InBodyPdfUseCases {

    private static final Logger log = LoggerFactory.getLogger(InBodyPdfReportService.class);

    private final InBodyMeasurements inBodyMeasurementsPort;

    // ── Palette couleurs InBody (fidèle à l'original imprimé couleur) ───────────
    // Texte & neutres
    private static final DeviceRgb BLACK       = new DeviceRgb(0,   0,   0);
    private static final DeviceRgb DARK        = new DeviceRgb(25,  25,  25);
    private static final DeviceRgb DARK_GRAY   = new DeviceRgb(60,  60,  60);
    private static final DeviceRgb MID_GRAY    = new DeviceRgb(110, 110, 110);
    private static final DeviceRgb LIGHT_GRAY  = new DeviceRgb(210, 210, 218);
    private static final DeviceRgb VLIGHT_GRAY = new DeviceRgb(247, 249, 252);
    private static final DeviceRgb WHITE       = new DeviceRgb(255, 255, 255);
    // Rouge InBody (logo + séparateur)
    private static final DeviceRgb RED         = new DeviceRgb(180, 30,  20);
    // Barres : zone normale = bleu InBody, fond = gris clair
    private static final DeviceRgb BAR_FILL    = new DeviceRgb(50,  110, 185);  // bleu acier
    private static final DeviceRgb BAR_BG      = new DeviceRgb(218, 228, 240);  // bleu très clair
    // En-têtes de sections : fond bleu pâle (identique à l'original)
    private static final DeviceRgb SEC_TITLE_BG = new DeviceRgb(220, 234, 248); // bleu ciel pâle
    private static final DeviceRgb HDR_BG       = new DeviceRgb(237, 244, 252); // bleu glacé
    private static final DeviceRgb STRIPE_A     = new DeviceRgb(255, 255, 255); // blanc pur
    private static final DeviceRgb STRIPE_B     = new DeviceRgb(244, 248, 254); // bleu très pâle
    // Couleurs supplémentaires pour les zones de barres
    private static final DeviceRgb ZONE_LOW    = new DeviceRgb(248, 215, 210);  // rouge pâle (inférieur)
    private static final DeviceRgb ZONE_NORMAL = new DeviceRgb(195, 220, 245);  // bleu pâle (normal)
    private static final DeviceRgb ZONE_HIGH   = new DeviceRgb(200, 235, 210);  // vert pâle (supérieur)
    private static final DeviceRgb FILL_LOW    = new DeviceRgb(200, 50,  40);   // rouge foncé
    private static final DeviceRgb FILL_NORMAL = new DeviceRgb(50,  110, 185);  // bleu InBody
    private static final DeviceRgb FILL_HIGH   = new DeviceRgb(45,  155, 75);   // vert foncé

    private static final DateTimeFormatter DT_FMT    = DateTimeFormatter.ofPattern("dd.MM.yyyy. HH:mm");
    private static final DateTimeFormatter SHORT_FMT  = DateTimeFormatter.ofPattern("dd.MM.yy");
    private static final DateTimeFormatter SHORT_FMT2 = DateTimeFormatter.ofPattern("dd.MM.yy\nHH:mm");

    // units and layout constants (points)
    private static final float PAGE_MARGIN_PT = 12f; // global margin used by Document
    private static final float COL_LEFT_PERCENT = 62f; // left column percent
    private static final float COL_RIGHT_PERCENT = 38f; // right column percent

    // standard font sizes used throughout the report (easier to tune)
    private static final float FONT_SIZE_TITLE = 14f;
    private static final float FONT_SIZE_SECTION = 9f;
    private static final float FONT_SIZE_SMALL = 6f;
    private static final float FONT_SIZE_SCORE = 44f;

    // graphic element sizes
    private static final float SEG_BAR_HEIGHT_PX = 10f; // height used for large segment bars
    private static final float PERCENT_BAR_HEIGHT_PX = 7f; // height used for small percent bars

    // resource path for optional embedded fonts
    private static final String EMBEDDED_FONT_REGULAR = "src/main/resources/fonts/InBody-Regular.ttf";
    private static final String EMBEDDED_FONT_BOLD = "src/main/resources/fonts/InBody-Bold.ttf";

    public InBodyPdfReportService(InBodyMeasurements inBodyMeasurementsPort) {
        this.inBodyMeasurementsPort = inBodyMeasurementsPort;
    }

    // ══════════════════════════════════════════════════════════════════════════
    // Contrats UseCase
    // ══════════════════════════════════════════════════════════════════════════

    @Override
    public List<InBodyReportSummary> getReportsByPatient(Integer patientId) {
        return inBodyMeasurementsPort.findReportSummariesByPatientId(patientId);
    }

    @Override
    public InBodyMeasurement getMeasurementById(Integer measurementId) {
        return inBodyMeasurementsPort.findMeasurementById(measurementId)
                .orElseThrow(() -> new IllegalArgumentException("Measurement not found: " + measurementId));
    }

    @Override
    public List<InBodyReportSummary> getPatientsWithReportsByNutritionist(Integer nutritionistId) {
        return inBodyMeasurementsPort.findPatientsWithMeasurementsByNutritionist(nutritionistId);
    }

    @Override
    public byte[] generatePdfReport(Integer measurementId, ReportType type, String nutritionistName) {
        InBodyMeasurement m = inBodyMeasurementsPort.findMeasurementById(measurementId)
                .orElseThrow(() -> new IllegalArgumentException("Measurement not found: " + measurementId));

        boolean withHistory = (type == ReportType.WITH_HISTORY || type == ReportType.WITH_HISTORY_AND_ANALYSIS);
        List<InBodyReportSummary> history = withHistory
                ? inBodyMeasurementsPort.findReportSummariesByPatientId(m.getPatientId())
                : List.of();

        return buildPdf(m, type, history, nutritionistName);
    }

    // ══════════════════════════════════════════════════════════════════════════
    // Constructeur PDF principal
    // ══════════════════════════════════════════════════════════════════════════

    private byte[] buildPdf(InBodyMeasurement m, ReportType type,
                            List<InBodyReportSummary> history, String nutritionistName) {
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream()) {
            PdfDocument pdf = new PdfDocument(new PdfWriter(baos));
            Document doc   = new Document(pdf, PageSize.A4);
            doc.setMargins(PAGE_MARGIN_PT, PAGE_MARGIN_PT, PAGE_MARGIN_PT, PAGE_MARGIN_PT);

            // attempt to load embedded fonts if present to better match the visuals
            PdfFont bold;
            PdfFont regular;
            try {
                if (new java.io.File(EMBEDDED_FONT_BOLD).exists() && new java.io.File(EMBEDDED_FONT_REGULAR).exists()) {
                    regular = PdfFontFactory.createFont(EMBEDDED_FONT_REGULAR, PdfEncodings.IDENTITY_H, true);
                    bold = PdfFontFactory.createFont(EMBEDDED_FONT_BOLD, PdfEncodings.IDENTITY_H, true);
                } else {
                    bold = PdfFontFactory.createFont(StandardFonts.HELVETICA_BOLD);
                    regular = PdfFontFactory.createFont(StandardFonts.HELVETICA);
                }
            } catch (Exception fe) {
                // fallback to standard fonts if embedding fails
                bold = PdfFontFactory.createFont(StandardFonts.HELVETICA_BOLD);
                regular = PdfFontFactory.createFont(StandardFonts.HELVETICA);
            }

            // ── PAGE 1 : Composition corporelle ──────────────────────────────
            buildPage1(doc, pdf, m, history, bold, regular, nutritionistName);
            buildFooter(doc, regular);

            // ── PAGE 2 : Eau corporelle ───────────────────────────────────────
            doc.add(new AreaBreak(AreaBreakType.NEXT_PAGE));
            buildPage2(doc, pdf, m, history, bold, regular, nutritionistName);
            buildFooter(doc, regular);

            // ── PAGE 3 : Analyse (optionnel) ──────────────────────────────────
            if (type == ReportType.WITH_HISTORY_AND_ANALYSIS) {
                doc.add(new AreaBreak(AreaBreakType.NEXT_PAGE));
                buildPage3(doc, pdf, m, history, bold, regular);
                buildFooter(doc, regular);
            }

            doc.close();
            return baos.toByteArray();
        } catch (Exception e) {
            log.error("PDF generation failed for measurement {}", m.getId(), e);
            throw new RuntimeException("PDF generation failed", e);
        }
    }

    // ══════════════════════════════════════════════════════════════════════════
    // EN-TÊTE COMMUN (page 1 uniquement — identique à l'original)
    // ══════════════════════════════════════════════════════════════════════════

    private void buildHeader(Document doc, InBodyMeasurement m,
                             PdfFont bold, PdfFont regular,
                             String nutritionistName, boolean waterPage) {
        // Ligne logo + cabinet
        Table hdr = new Table(UnitValue.createPercentArray(new float[]{40, 20, 40}))
                .setWidth(UnitValue.createPercentValue(100))
                .setMarginBottom(1);

        // Logo InBody
        Cell logoCell = nb().setPadding(2).setVerticalAlignment(VerticalAlignment.MIDDLE);
        Paragraph logo = new Paragraph()
                .add(new Text("In").setFont(bold).setFontSize(22).setFontColor(RED))
                .add(new Text("Body").setFont(bold).setFontSize(22).setFontColor(DARK))
                .setMargin(0);
        logoCell.add(logo);
        if (waterPage) {
            logoCell.add(p(" d'eau corporelle", bold, 10).setFontColor(DARK));
        }
        hdr.addCell(logoCell);

        // Centre : modèle
        hdr.addCell(nb().setTextAlignment(TextAlignment.CENTER)
                .setVerticalAlignment(VerticalAlignment.BOTTOM).setPadding(2)
                .add(p("[InBody770]", regular, 7).setFontColor(MID_GRAY)));

        // Droite : cabinet
        Cell cab = nb().setTextAlignment(TextAlignment.RIGHT).setPadding(2);
        cab.add(p("CABINET NUTRITIONNISTE", bold, 7).setFontColor(DARK_GRAY));
        cab.add(p(safe(nutritionistName), bold, 10).setFontColor(BLACK));
        cab.add(p("29 711 811", regular, 8).setFontColor(DARK_GRAY));
        hdr.addCell(cab);
        doc.add(hdr);

        // Ligne de séparation rouge (fidèle à l'original)
        doc.add(new LineSeparator(new SolidLine(1.5f) {{ setColor(RED); }}).setMarginBottom(2));

        // Bande patient (5 colonnes comme dans l'original)
        Table pat = new Table(UnitValue.createPercentArray(new float[]{22, 11, 7, 7, 53}))
                .setWidth(UnitValue.createPercentValue(100))
                .setBackgroundColor(new DeviceRgb(240, 246, 253))
                .setBorder(new SolidBorder(new DeviceRgb(180, 210, 235), 0.5f))
                .setMarginBottom(3);
        pat.addCell(patCell("ID",                    safe(m.getMobileNumber()),                                        bold, regular));
        pat.addCell(patCell("Taille",                fmt(m.getHeight()) + "cm",                                        bold, regular));
        pat.addCell(patCell("Âge",                   fmt(m.getAge()),                                                   bold, regular));
        pat.addCell(patCell("Sexe",                  fmtGender(m.getGender()),                                         bold, regular));
        pat.addCell(patCell("Date / Heure du test",
                m.getTestDateTime() != null ? m.getTestDateTime().format(DT_FMT) : "-",                               bold, regular));
        doc.add(pat);
    }

    private Cell patCell(String label, String value, PdfFont bold, PdfFont regular) {
        Cell c = nb().setBorderRight(new SolidBorder(new DeviceRgb(180, 210, 235), 0.5f)).setPadding(3);
        c.add(p(label, regular, 5.5f).setFontColor(new DeviceRgb(80, 120, 170)));
        c.add(p(value, bold, 9).setFontColor(DARK));
        return c;
    }

    private void buildFooter(Document doc, PdfFont regular) {
        doc.add(new LineSeparator(new SolidLine(0.3f)).setMarginTop(4));
        doc.add(p("Ver.LookinBody120 4.0.0.7 · S/N: IB23000478  |  " +
                        "Copyright©1996~ by InBody Co., Ltd. All rights reserved.  BR-French-C7-D-191010",
                regular, 5).setFontColor(MID_GRAY).setTextAlignment(TextAlignment.CENTER));
    }

    // ══════════════════════════════════════════════════════════════════════════
    // PAGE 1 — Composition corporelle
    // Structure originale :
    //   GAUCHE (58%) : Analyse composition, Bilan général, Bilan morphologique,
    //                  Masse maigre segmentaire, ECW/TBW, Historique, Impédance
    //   DROITE (42%) : Score InBody, SGV, Recommandations, Symétrie,
    //                  Graisse par segment, Paramètres de recherche, Angle de phase
    // ══════════════════════════════════════════════════════════════════════════

    private void buildPage1(Document doc, PdfDocument pdf,
                            InBodyMeasurement m, List<InBodyReportSummary> history,
                            PdfFont bold, PdfFont regular, String nutritionistName) {
        buildHeader(doc, m, bold, regular, nutritionistName, false);

        // ═══════════════════════════════════════════════════════════════════
        // STRUCTURE EXACTE ORIGINALE INBODY — PAGE 1
        //
        // UN SEUL tableau 2 colonnes couvre TOUTE la page (après l en-tête).
        //   COLONNE GAUCHE  (62%) :
        //     - Analyse composition corporelle  (pleine largeur colonne)
        //     - Bilan Général
        //     - Bilan Morphologique
        //     - Masse Maigre Segmentaire (double barre)
        //     - ECW/TBW
        //     - Historique (graphique temporel en bas)
        //
        //   COLONNE DROITE  (38%) — sidebar fixe du haut jusqu en bas :
        //     - Score InBody  (grand chiffre, en HAUT)
        //     - Surface Graisse Viscérale (graphique)
        //     - Recommandations (Poids cible / Masse grasse / Muscle)
        //     - Evaluation Symetrie
        //     - Analyse Graisse par Segment
        //     - Paramètres de Recherche  (MILIEU droite)
        //     - Angle de phase
        //     - Impédance compact (BAS droite)
        // ═══════════════════════════════════════════════════════════════════

        // Table principale unique 62/38 — toute la page
        Table main = new Table(UnitValue.createPercentArray(new float[]{COL_LEFT_PERCENT, COL_RIGHT_PERCENT}))
                .setWidth(UnitValue.createPercentValue(100))
                .setMarginTop(0);

        // ── COLONNE GAUCHE (62%) ──────────────────────────────────────────────
        Cell left = nb().setPaddingRight(4);
        left.add(secCompositionCorporelle(m, bold, regular));
        left.add(secBilanGeneral(m, bold, regular));
        left.add(secBilanMorphologique(m, bold, regular));
        left.add(secMasseMaigreSegmentaire(m, bold, regular));
        left.add(secEcwTbw(m, bold, regular));
        left.add(secHistorique(m, history, bold, regular, pdf));

        // ── COLONNE DROITE (38%) — sidebar fixe ──────────────────────────────
        Cell right = nb().setPaddingLeft(2)
                .setBorderLeft(new SolidBorder(LIGHT_GRAY, 0.5f));
        right.add(secScoreInBody(m, bold, regular));
        right.add(secSGV(m, bold, regular));
        right.add(secRecommandations(m, bold, regular));
        right.add(secSymetrie(bold, regular));
        right.add(secGraisseParSegment(m, bold, regular));
        right.add(secParametresRechercheCompact(m, bold, regular));
        right.add(secAnglePhase(m, bold, regular));
        right.add(secImpedanceCompact(m, bold, regular));

        main.addCell(left);
        main.addCell(right);
        doc.add(main);
    }

    // ══════════════════════════════════════════════════════════════════════════
    // PAGE 2 — Eau corporelle  (fidèle à l'original "d'eau corporelle")
    // Structure originale :
    //   Mini-bande InBody "d'eau corporelle" (remplace le grand en-tête)
    //   GAUCHE (58%) : Composition hydrique, ECW/TBW, Eau par segment,
    //                  Ratios EEC par segment, Historique, Impédance
    //   DROITE (42%) : Résumé composition hydrique, Résumé analyse composition,
    //                  Résumé bilan général, Résumé bilan morphologique,
    //                  Paramètres recherche résumé, Angle de phase
    // ══════════════════════════════════════════════════════════════════════════

    private void buildPage2(Document doc, PdfDocument pdf,
                            InBodyMeasurement m, List<InBodyReportSummary> history,
                            PdfFont bold, PdfFont regular, String nutritionistName) {
        // Mini-bande de continuité (remplace l'en-tête complet sur p.2)
        Table band = new Table(UnitValue.createPercentArray(new float[]{50, 50}))
                .setWidth(UnitValue.createPercentValue(100))
                .setMarginBottom(4);

        Cell bl = nb().setPadding(3);
        Paragraph logoLine = new Paragraph()
                .add(new Text("In").setFont(bold).setFontSize(16).setFontColor(RED))
                .add(new Text("Body").setFont(bold).setFontSize(16).setFontColor(DARK))
                .add(new Text(" d'eau corporelle").setFont(bold).setFontSize(9).setFontColor(DARK_GRAY))
                .setMargin(0);
        bl.add(logoLine);
        band.addCell(bl);

        Cell br = nb().setPadding(3).setTextAlignment(TextAlignment.RIGHT)
                .setVerticalAlignment(VerticalAlignment.BOTTOM);
        br.add(p(safe(m.getMobileNumber()) + "  |  " + fmtGender(m.getGender()) +
                        "  |  " + fmt(m.getAge()) + " ans  |  " + fmt(m.getHeight()) + " cm  |  " +
                        (m.getTestDateTime() != null ? m.getTestDateTime().format(DT_FMT) : "-"),
                regular, 6.5f).setFontColor(DARK_GRAY));
        band.addCell(br);
        doc.add(band);

        doc.add(new LineSeparator(new SolidLine(0.8f) {{ setColor(new DeviceRgb(50, 110, 185)); }}).setMarginBottom(3));

        // Corps en 2 colonnes
        Table main = twoCol(58, 42);
        Cell lc = nb().setPaddingRight(4);
        Cell rc = nb().setPaddingLeft(3);

        // ── GAUCHE ───────────────────────────────────────────────────────────
        lc.add(secCompositionHydrique(m, bold, regular));
        lc.add(secEcwTbwPage2(m, bold, regular));
        lc.add(secEauParSegment(m, bold, regular));
        lc.add(secRatiosEECParSegment(m, bold, regular));
        lc.add(secHistoriquePage2(m, history, bold, regular));
        lc.add(secImpedance(m, bold, regular));

        // ── DROITE ───────────────────────────────────────────────────────────
        rc.add(secResumeCompositionHydrique(m, bold, regular));
        rc.add(secResumeCompositionCorporelle(m, bold, regular));
        rc.add(secResumeBilanGeneral(m, bold, regular));
        rc.add(secResumeBilanMorphologique(m, bold, regular));
        rc.add(secResumeParametresRecherche(m, bold, regular));
        rc.add(secAnglePhase(m, bold, regular));

        main.addCell(lc);
        main.addCell(rc);
        doc.add(main);
    }

