    private void buildPage3(Document doc, PdfDocument pdf,
                            InBodyMeasurement m, List<InBodyReportSummary> history,
                            PdfFont bold, PdfFont regular) {
        // Bannière rouge analyse
        Table banner = new Table(UnitValue.createPercentArray(new float[]{100}))
                .setWidth(UnitValue.createPercentValue(100))
                .setBackgroundColor(RED).setMarginBottom(5);
        Cell bc = nb().setPadding(5);
        bc.add(new Paragraph()
                .add(new Text("In").setFont(bold).setFontSize(14).setFontColor(WHITE))
                .add(new Text("Body").setFont(bold).setFontSize(14).setFontColor(new DeviceRgb(255, 200, 200)))
                .add(new Text("   Analyse & Tendances — Rapport Détaillé").setFont(bold).setFontSize(9).setFontColor(WHITE))
                .setMargin(0));
        bc.add(p("Patient : " + safe(m.getMobileNumber()) + "  |  " + fmtGender(m.getGender()) +
                        "  |  " + fmt(m.getAge()) + " ans  |  " + fmt(m.getHeight()) + " cm  |  " +
                        (m.getTestDateTime() != null ? m.getTestDateTime().format(DT_FMT) : "-"),
                regular, 6.5f).setFontColor(new DeviceRgb(255, 230, 230)));
        banner.addCell(bc);
        doc.add(banner);

        // Rangée 1 : courbes + radar
        Table r1 = twoCol(60, 40);
        Cell r1l = nb().setPaddingRight(4);
        Cell r1r = nb().setPaddingLeft(3);
        r1l.add(secCourbeTendance(m, history, bold, regular, pdf));
        r1r.add(secRadarChart(m, bold, regular, pdf));
        r1.addCell(r1l); r1.addCell(r1r);
        doc.add(r1);

        // Rangée 2 : donut + équilibre segmentaire
        Table r2 = twoCol(50, 50);
        Cell r2l = nb().setPaddingRight(4);
        Cell r2r = nb().setPaddingLeft(3);
        r2l.add(secDonutComposition(m, bold, regular, pdf));
        r2r.add(secEquilibreSegmentaire(m, bold, regular, pdf));
        r2.addCell(r2l); r2.addCell(r2r);
        doc.add(r2);

        doc.add(secInterpretationClinique(m, bold, regular));
        doc.add(secRecommandationsEnrichies(m, bold, regular));
    }

