    /**
     * "Analyse de la composition corporelle"
     * 4 rangées : Eau Corp. totale, Protéines, Minéraux non osseux, Masse grasse
     * + barre de composition horizontale en haut (4 colonnes : ECT / MM / MNG / Poids)
     * Exactement comme dans l'original page 1 haut gauche.
     */
    private Table secCompositionCorporelle(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Analyse de la composition corporelle", bold));

        // En-tête des 4 colonnes de composition
        Table hdr = new Table(UnitValue.createPercentArray(new float[]{24, 18, 46, 12}))
                .setWidth(UnitValue.createPercentValue(100))
                .setBackgroundColor(HDR_BG);
        hdr.addCell(hdrCell("", regular));
        hdr.addCell(hdrCell("Valeurs", regular));
        // Colonnes de composition (4 zones horizontales)
        Cell zc = nb().setBorderBottom(Border.NO_BORDER).setPadding(1);
        Table zones = new Table(UnitValue.createPercentArray(new float[]{25, 25, 25, 25})).setWidth(UnitValue.createPercentValue(100));
        for (String z : new String[]{"Eau Corp. totale", "Masse maigre", "Masse non grasse", "Poids"})
            zones.addCell(nb().setTextAlignment(TextAlignment.CENTER)
                    .add(p(z, regular, 4.5f).setFontColor(MID_GRAY)));
        zc.add(zones);
        hdr.addCell(zc);
        hdr.addCell(hdrCell("", regular));
        s.addCell(nb(0).add(hdr));

        // Rangées de données
        Table body = new Table(UnitValue.createPercentArray(new float[]{24, 18, 46, 12}))
                .setWidth(UnitValue.createPercentValue(100));

        // Eau corporelle totale
        compRow(body, "Eau Corporelle totale", "(L)",
                m.getTotalBodyWater(), m.getTbwLowerLimit(), m.getTbwUpperLimit(),
                20, 50, null, bold, regular);

        // Protéines
        compRow(body, "Protéines", "(kg)",
                m.getProtein(), m.getProteinLowerLimit(), m.getProteinUpperLimit(),
                4, 16, null, bold, regular);

        // Minéraux non osseux
        compRow(body, "Minéraux non osseux", "(kg)",
                m.getMinerals(), m.getMineralsLowerLimit(), m.getMineralsUpperLimit(),
                1.5, 5.0, null, bold, regular);

        // Masse grasse (avec poids affiché à droite)
        compRow(body, "Masse grasse", "(kg)",
                m.getBodyFatMass(), m.getBfmLowerLimit(), m.getBfmUpperLimit(),
                0, 50, fmt(m.getWeight()) + " kg", bold, regular);

        s.addCell(nb(0).add(body));
        return s;
    }

    private void compRow(Table t, String label, String unit, Double val,
                         Double lo, Double hi, double sMin, double sMax,
                         String rightLabel, PdfFont bold, PdfFont regular) {
        // Colonne label
        Cell lc = nb(1);
        lc.add(p(label, regular, 6.5f).setFontColor(DARK_GRAY));
        lc.add(p(unit,  regular, 5.5f).setFontColor(MID_GRAY));
        t.addCell(lc);
        // Valeur
        t.addCell(nb(1).setTextAlignment(TextAlignment.CENTER)
                .setVerticalAlignment(VerticalAlignment.MIDDLE)
                .add(p("(" + range(lo, hi) + ")", regular, 5).setFontColor(MID_GRAY))
                .add(p(fmt(val), bold, 9)));
        // Barre
        t.addCell(nb(0).add(buildColorBar(val, lo, hi, sMin, sMax, 10, regular)));
        // Droite (poids total pour dernière ligne)
        Cell rc = nb(1).setTextAlignment(TextAlignment.RIGHT)
                .setVerticalAlignment(VerticalAlignment.MIDDLE);
        if (rightLabel != null) rc.add(p(rightLabel, bold, 8).setFontColor(DARK));
        t.addCell(rc);
    }

