    /**
     * "Masse Maigre Segmentaire"
     * Structure originale : 4 colonnes — label | valeur kg/(%) | DEUX barres | Ratio EEC
     * La cellule centrale contient deux barres superposées :
     *   - Barre 1 (supérieure) : kg, échelle basée sur poids idéal (80–120%)
     *   - Barre 2 (inférieure) : %, échelle basée sur poids actuel  (80–120%)
     * Même en-tête légende "Basé sur poids idéal —— Basé sur poids actuel"
     */

    private Table secMasseMaigreSegmentaire(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Masse Maigre Segmentaire", bold));

        // En-tête légende : 4 colonnes identiques à l'original
        Table legHdr = new Table(UnitValue.createPercentArray(new float[]{22, 9, 55, 14}))
                .setWidth(UnitValue.createPercentValue(100)).setBackgroundColor(HDR_BG);
        legHdr.addCell(hdrCell("", regular));
        legHdr.addCell(hdrCell("", regular));
        Cell legendCell = nb(1).setTextAlignment(TextAlignment.CENTER);
        legendCell.add(p("Inferieur      Normal      Superieur", regular, 4.5f).setFontColor(MID_GRAY));
        legendCell.add(p("Poids ideal  ——  Poids actuel", regular, 4f).setFontColor(MID_GRAY));
        legHdr.addCell(legendCell);
        legHdr.addCell(hdrCell("Ratio EEC", regular));
        s.addCell(nb(0).add(legHdr));

        // Tableau des 5 segments
        Table t = new Table(UnitValue.createPercentArray(new float[]{22, 9, 55, 14}))
                .setWidth(UnitValue.createPercentValue(100));

        segMaigreRow(t, "Membre Superieur Droit",  m.getFfmRightArm(), m.getFfmPercentRightArm(), m.getEcwTbwOfRightArm(), bold, regular);
        segMaigreRow(t, "Membre Superieur Gauche", m.getFfmLeftArm(),  m.getFfmPercentLeftArm(),  m.getEcwTbwOfLeftArm(),  bold, regular);
        segMaigreRow(t, "Tronc",                   m.getFfmTrunk(),    m.getFfmPercentTrunk(),    m.getEcwTbwOfTrunk(),    bold, regular);
        segMaigreRow(t, "Membre Inferieur Droit",  m.getFfmRightLeg(), m.getFfmPercentRightLeg(), m.getEcwTbwOfRightLeg(), bold, regular);
        segMaigreRow(t, "Membre Inferieur Gauche", m.getFfmLeftLeg(),  m.getFfmPercentLeftLeg(),  m.getEcwTbwOfLeftLeg(),  bold, regular);

        s.addCell(nb(0).add(t));
        return s;
    }

    /**
     * Rangée segmentaire avec DEUX barres superposées (kg ET %) comme dans l original.
     * Barre supérieure = kg (poids idéal), barre inférieure = % (poids actuel).
     * Chaque barre a : zones gris | zone noire centrale | zones gris + marqueur triangle.
     */
    private void segMaigreRow(Table t, String fullLabel,
                              Double valKg, Double valPct, Double ecwRatio,
                              PdfFont bold, PdfFont regular) {
        // Colonne label
        Cell lc = nb(1);
        lc.add(p(fullLabel, regular, 6f));
        lc.add(p("(kg)", regular, 4.5f).setFontColor(MID_GRAY));
        lc.add(p("(%)", regular, 4.5f).setFontColor(MID_GRAY));
        t.addCell(lc);

        // Colonne valeurs numériques (kg sur ligne 1, % sur ligne 2)
        Cell vc = nb(1).setTextAlignment(TextAlignment.CENTER);
        vc.add(p(fmt(valKg), bold, 7.5f));
        vc.add(p(fmt(valPct), regular, 6f).setFontColor(MID_GRAY));
        t.addCell(vc);

        // Colonne double barre
        Cell bc = nb(0);
        // Barre 1 : kg (poids idéal, 80–120%)
        bc.add(buildSegMaigreBar(valKg != null ? (valPct != null ? valPct : 100.0) : 100.0,
                80, 120, regular));
        // Séparateur minuscule entre les deux barres
        bc.add(p(" ", regular, 1));
        // Barre 2 : % (poids actuel, 80–120%)
        bc.add(buildSegMaigreBar(valPct, 80, 120, regular));
        t.addCell(bc);

        // Ratio EEC
        t.addCell(nb(1).setTextAlignment(TextAlignment.CENTER)
                .setVerticalAlignment(VerticalAlignment.MIDDLE)
                .add(p(fmt3(ecwRatio), regular, 7.5f)));
    }

