    /**
     * "Score InBody" — grand chiffre centré + barre de score 0/60/100
     */
    private Table secScoreInBody(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Score InBody", bold));

        int score = m.getInbodyScore() != null ? m.getInbodyScore() : 0;

        Cell cc = nb(4).setTextAlignment(TextAlignment.CENTER)
                .setBackgroundColor(new DeviceRgb(240, 246, 253));

        DeviceRgb scoreNumColor = score >= 80 ? FILL_HIGH : score >= 60 ? FILL_NORMAL : FILL_LOW;
        cc.add(p(String.valueOf(score), bold, 44).setFontColor(scoreNumColor));
        cc.add(p("/100 Points", regular, 9).setFontColor(new DeviceRgb(80, 120, 170)));

        // Barre de score
        cc.add(buildScoreBar(score, bold, regular));

        cc.add(new LineSeparator(new SolidLine(0.3f)).setMarginTop(4).setMarginBottom(2));
        cc.add(p("* Le score InBody reflète l'évaluation de la composition\n" +
                        "corporelle en un chiffre. Une personne musclée peut obtenir plus de 100 points.",
                regular, 5.5f).setFontColor(MID_GRAY));

        s.addCell(cc);
        return s;
    }

    private Table buildScoreBar(int score, PdfFont bold, PdfFont regular) {
        Table wrap = new Table(UnitValue.createPercentArray(new float[]{100}))
                .setWidth(UnitValue.createPercentValue(100)).setMarginTop(4);

        // Graduations
        Table scale = new Table(UnitValue.createPercentArray(new float[]{60, 20, 20})).setWidth(UnitValue.createPercentValue(100));
        scale.addCell(nb(0).add(p("0", regular, 5).setFontColor(MID_GRAY)));
        scale.addCell(nb(0).setTextAlignment(TextAlignment.CENTER).add(p("60", regular, 5).setFontColor(MID_GRAY)));
        scale.addCell(nb(0).setTextAlignment(TextAlignment.RIGHT).add(p("100", regular, 5).setFontColor(MID_GRAY)));
        wrap.addCell(nb(0).add(scale));

        // 3 zones colorées : rouge (0-60) | bleu (60-80) | vert (80-100)
        Table bar = new Table(UnitValue.createPercentArray(new float[]{60, 20, 20})).setWidth(UnitValue.createPercentValue(100));
        bar.addCell(new Cell().setHeight(8).setBackgroundColor(ZONE_LOW).setBorder(Border.NO_BORDER));
        bar.addCell(new Cell().setHeight(8).setBackgroundColor(ZONE_NORMAL).setBorder(Border.NO_BORDER));
        bar.addCell(new Cell().setHeight(8).setBackgroundColor(ZONE_HIGH).setBorder(Border.NO_BORDER));
        wrap.addCell(nb(0).add(bar));

        // Marqueur ▼ coloré selon le score
        DeviceRgb scoreColor = score >= 80 ? FILL_HIGH : score >= 60 ? FILL_NORMAL : FILL_LOW;
        float pos = Math.max(2f, Math.min(97f, score));
        float ml = pos - 3f, mr = Math.max(0.5f, 100f - pos - 3f);
        Table mk = new Table(UnitValue.createPercentArray(new float[]{ml, 6, mr})).setWidth(UnitValue.createPercentValue(100));
        mk.addCell(nb(0));
        mk.addCell(nb(0).setTextAlignment(TextAlignment.CENTER).add(p("▼", regular, 8).setFontColor(scoreColor)));
        mk.addCell(nb(0));
        wrap.addCell(nb(0).add(mk));
        return wrap;
    }

    /**
     * "Surface de graisse viscérale" — valeur SGV + graphique SGV par âge
     */
    private Table secSGV(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Surface de graisse viscérale", bold));

        // Valeur principale
        Table top = new Table(UnitValue.createPercentArray(new float[]{55, 45}))
                .setWidth(UnitValue.createPercentValue(100));
        Cell tl = nb(2);
        tl.add(p("SGV(cm²)", regular, 6.5f).setFontColor(MID_GRAY));
        tl.add(p(fmt(m.getVfaVisceralFatArea()), bold, 15).setFontColor(RED));
        top.addCell(tl);
        Cell tr = nb(2);
        if (m.getVflVisceralFatLevel() != null)
            tr.add(p("Niveau : " + m.getVflVisceralFatLevel(), regular, 7));
        top.addCell(tr);

        Cell cc = nb(2);
        cc.add(top);

        // Grille SGV par âge (Y: 0-200, X: 20-80)
        Table chart = new Table(UnitValue.createPercentArray(new float[]{10, 90}))
                .setWidth(UnitValue.createPercentValue(100));

        Cell ya = nb(0).setTextAlignment(TextAlignment.RIGHT);
        for (String label : new String[]{"200", "150", "100", "50", ""})
            ya.add(p(label, regular, 5).setFontColor(MID_GRAY));
        chart.addCell(ya);

        Cell area = nb(1).setBorder(new SolidBorder(LIGHT_GRAY, 0.5f))
                .setBackgroundColor(VLIGHT_GRAY);
        // Grille simplifiée (4×5 cellules)
        Table grid = new Table(UnitValue.createPercentArray(new float[]{25, 25, 25, 25})).setWidth(UnitValue.createPercentValue(100));
        for (int row = 0; row < 5; row++)
            for (int col = 0; col < 4; col++) {
                boolean norm = (row == 1 || row == 2);
                grid.addCell(new Cell().setHeight(9)
                        .setBackgroundColor(norm ? new DeviceRgb(220, 220, 220) : VLIGHT_GRAY)
                        .setBorder(new SolidBorder(LIGHT_GRAY, 0.3f)));
            }
        area.add(grid);
        if (m.getVfaVisceralFatArea() != null && m.getAge() != null)
            area.add(p("✦ " + fmt(m.getVfaVisceralFatArea()) + " cm² (âge " + m.getAge() + ")",
                    bold, 6).setFontColor(DARK));
        // Axe X
        Table xa = new Table(UnitValue.createPercentArray(new float[]{25, 25, 25, 25})).setWidth(UnitValue.createPercentValue(100));
        for (String a : new String[]{"20", "40", "60", "80"})
            xa.addCell(nb(0).setTextAlignment(TextAlignment.CENTER)
                    .add(p(a, regular, 5).setFontColor(MID_GRAY)));
        area.add(xa);
        area.add(p("Âge", regular, 6).setFontColor(MID_GRAY).setTextAlignment(TextAlignment.CENTER));
        chart.addCell(area);
        cc.add(chart);

        s.addCell(cc);
        return s;
    }

