    /**
     * "Analyse de la graisse par segment"
     * Lignes : MSD, MSG, TR, MID, MIG  avec barre + pourcentage
     */
    private Table secGraisseParSegment(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Analyse de la graisse par segment", bold));

        // En-tête
        Table hdr = new Table(UnitValue.createPercentArray(new float[]{30, 48, 22}))
                .setWidth(UnitValue.createPercentValue(100)).setBackgroundColor(HDR_BG);
        hdr.addCell(hdrCell("Segment", regular));
        hdr.addCell(hdrCell("Barre", regular));
        hdr.addCell(hdrCell("%", regular));
        s.addCell(nb(0).add(hdr));

        Table t = new Table(UnitValue.createPercentArray(new float[]{30, 48, 22}))
                .setWidth(UnitValue.createPercentValue(100));

        fatRow(t, "MSD", "(Membre Supérieur Droit)",  m.getBfmOfRightArm(), m.getBfmPercentOfRightArm(), bold, regular);
        fatRow(t, "MSG", "(Membre Supérieur Gauche)", m.getBfmOfLeftArm(),  m.getBfmPercentOfLeftArm(),  bold, regular);
        fatRow(t, "TR",  "(Tronc)",                   m.getBfmOfTrunk(),    m.getBfmPercentOfTrunk(),    bold, regular);
        fatRow(t, "MID", "(Membre Inférieur Droit)",  m.getBfmOfRightLeg(), m.getBfmPercentOfRightLeg(), bold, regular);
        fatRow(t, "MIG", "(Membre Inférieur Gauche)", m.getBfmOfLeftLeg(),  m.getBfmPercentOfLeftLeg(),  bold, regular);

        s.addCell(nb(0).add(t));
        return s;
    }

    private void fatRow(Table t, String abbr, String sub, Double bfm, Double pct,
                        PdfFont bold, PdfFont regular) {
        // Ligne compacte pour la sidebar étroite (28%)
        Cell lc = nb(1);
        lc.add(p(abbr, bold, 6.5f));
        lc.add(p("(" + fmt(bfm) + " kg)", regular, 4.5f).setFontColor(MID_GRAY));
        t.addCell(lc);

        // Barre de graisse : couleur selon la zone (rouge si > 150%, orange sinon)
        double sp = pct != null ? pct : 0;
        float fw = (float) Math.max(0.5, Math.min(99.5, sp / 10.0));
        DeviceRgb fatColor = sp > 200 ? new DeviceRgb(200, 50, 40)
                : sp > 150 ? new DeviceRgb(220, 120, 50)
                : new DeviceRgb(50, 110, 185);
        Table bar = new Table(UnitValue.createPercentArray(new float[]{fw, Math.max(0.5f, 100 - fw)}))
                .setWidth(UnitValue.createPercentValue(100));
        bar.addCell(new Cell().setHeight(6).setBackgroundColor(fatColor).setBorder(Border.NO_BORDER));
        bar.addCell(new Cell().setHeight(6).setBackgroundColor(BAR_BG).setBorder(Border.NO_BORDER));
        t.addCell(nb(1).add(bar));

        t.addCell(nb(1).setTextAlignment(TextAlignment.RIGHT)
                .setVerticalAlignment(VerticalAlignment.MIDDLE)
                .add(p(fmt(pct) + "%", bold, 6.5f)));
    }

    /**
     * "Paramètres de recherche"
