    /**
     * "Composition Hydrique"
     * Lignes ECT, EIC, EEC avec barres % (70–170%)
     * En-tête : colonnes Inférieur / Normal (coloriées)
     */
    private Table secCompositionHydrique(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Composition Hydrique", bold));

        // En-tête spécial avec zones colorées
