    /**
     * "Analyse des ratios EEC par segment"
     * Graphique en points pour 5 segments (Bras D/G, Tronc, Jambe D/G)
     * Axe Y : 0.36–0.43
     */
    /**
     * CORRECTION 4 — "Analyse des ratios EEC par segment"
     * Graphique imposant et dédié, centré sur la page 2 gauche.
     * Structure originale :
     *   - Axe Y à gauche avec labels de zones : "Elevé" / "Légèrement élevé" / "Normal"
     *   - Valeurs numériques 0,36–0,43 sur l'axe Y
     *   - 5 colonnes (un par segment) avec le point ● positionné à la bonne hauteur
     *   - Label du segment en bas de chaque colonne
     *   - Valeur numérique affichée sur le point
     * La hauteur du point est calculée proportionnellement à l'axe Y (0,36–0,43).
     */
    private Table secRatiosEECParSegment(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Analyse des ratios EEC par segment", bold));

        String[] segs = {"Bras droit", "Bras gauche", "Tronc", "Jambe droite", "Jambe gauche"};
        Double[] vals = {m.getEcwTbwOfRightArm(), m.getEcwTbwOfLeftArm(),
                m.getEcwTbwOfTrunk(), m.getEcwTbwOfRightLeg(), m.getEcwTbwOfLeftLeg()};

        // Grille graphique : col Y (15%) + 5 colonnes segments (17% chacune)
        Table chart = new Table(UnitValue.createPercentArray(new float[]{13, 87}))
                .setWidth(UnitValue.createPercentValue(100));

        // ── Axe Y gauche : labels numériques + zones textuelles ──────────────
        Cell ya = nb(0).setTextAlignment(TextAlignment.RIGHT).setPaddingRight(2);
        // 8 valeurs Y de 0,43 (haut) à 0,36 (bas)
        String[] yLabels = {"0,43","0,42","0,41","0,40","0,39","0,38","0,37","0,36"};
        // Zones textuelles (positionnées sur l'axe)
        // 0,41+ = Elevé ; 0,39–0,41 = Légèrement élevé ; <0,39 = Normal
        ya.add(p("Elevé", bold, 5).setFontColor(DARK));
        ya.add(p("", regular, 2));
        ya.add(p("Leg. eleve", bold, 5).setFontColor(DARK));
        ya.add(p("", regular, 2));
        ya.add(p("Normal", bold, 5).setFontColor(DARK));
        ya.add(new LineSeparator(new SolidLine(0.3f)).setMarginTop(1).setMarginBottom(1));
        for (String lbl : yLabels)
            ya.add(p(lbl, regular, 5).setFontColor(MID_GRAY));
        chart.addCell(ya);

        // ── Zone de tracé : 5 colonnes ────────────────────────────────────────
        // Y range : 0,36 (bas) → 0,43 (haut), soit 7 divisions de 0,01
        double yMin = 0.36, yMax = 0.43, yRange = yMax - yMin;
        int totalRows = 8; // nombre de lignes de la grille

        Table plot = new Table(UnitValue.createPercentArray(new float[]{20, 20, 20, 20, 20}))
                .setWidth(UnitValue.createPercentValue(100))
                .setBorder(new SolidBorder(LIGHT_GRAY, 0.3f));

        for (int i = 0; i < 5; i++) {
            double v = vals[i] != null ? vals[i] : 0.385;
            // Position relative : 0=bas, 1=haut
            double relPos = Math.max(0.0, Math.min(1.0, (v - yMin) / yRange));
            // Espace vide au-dessus du point (en unités de lignes de grille)
            int rowsAbove = (int) Math.round((1.0 - relPos) * (totalRows - 1));
            int rowsBelow = (totalRows - 1) - rowsAbove;
            if (rowsAbove < 0) rowsAbove = 0;
            if (rowsBelow < 0) rowsBelow = 0;

            // Fond coloré selon la zone
            DeviceRgb zoneBg;
            if (v >= 0.41)       zoneBg = new DeviceRgb(215, 215, 215); // élevé
            else if (v >= 0.39)  zoneBg = new DeviceRgb(230, 230, 230); // légèrement élevé
            else                 zoneBg = new DeviceRgb(245, 245, 245); // normal

            Cell col = nb(1).setTextAlignment(TextAlignment.CENTER)
                    .setBorder(new SolidBorder(LIGHT_GRAY, 0.2f))
                    .setBackgroundColor(zoneBg);

            // Espace au-dessus du point
            for (int r = 0; r < rowsAbove; r++)
                col.add(p(" ", regular, 5));

            // Le point avec sa valeur
            col.add(p("●", bold, 11).setFontColor(DARK));
            col.add(p(fmt3(vals[i]), bold, 6.5f));

            // Espace en dessous du point
            for (int r = 0; r < rowsBelow; r++)
                col.add(p(" ", regular, 5));

            // Label segment en bas
            col.add(new LineSeparator(new SolidLine(0.2f)));
            col.add(p(segs[i], regular, 5).setFontColor(MID_GRAY));
            plot.addCell(col);
        }
        chart.addCell(nb(0).add(plot));
        s.addCell(nb(0).add(chart));

        // Indicateurs de tendance
        if (n >= 2) {
            double dW = weights[n-1] - weights[0];
            double dS = smms[n-1] - smms[0];
            double dF = fats[n-1] - fats[0];
            Table trend = new Table(UnitValue.createPercentArray(new float[]{33, 33, 34})).setWidth(UnitValue.createPercentValue(100));
            trend.addCell(nb(1).add(p((dW > 0.5 ? "↑ +" : dW < -0.5 ? "↓ " : "→ ") + fmt(Math.abs(dW)) + " kg", bold, 6)));
            trend.addCell(nb(1).add(p((dS > 0.3 ? "↑ +" : dS < -0.3 ? "↓ " : "→ ") + fmt(Math.abs(dS)) + " kg", bold, 6)));
            trend.addCell(nb(1).add(p((dF > 0.5 ? "↑ +" : dF < -0.5 ? "↓ " : "→ ") + fmt(Math.abs(dF)) + "%", bold, 6)));
            s.addCell(nb(1).add(trend));
        }
        return s;
    }

    private Table secRadarChart(InBodyMeasurement m, PdfFont bold, PdfFont regular, PdfDocument pdf) {
        Table s = wrap();
        s.addCell(secTitleCell("Profil biométrique — Radar normalisé (0–100)", bold));
        Cell cc = nb(3);

        double[] axes = {
                clamp01(m.getInbodyScore(), 0, 100),
                clamp01(m.getSkeletalMuscleMass(), m.getSmmLowerLimit(), m.getSmmUpperLimit()),
                1.0 - clamp01(m.getPercentBodyFat(), m.getPbfLowerLimit(), m.getPbfUpperLimit()),
                1.0 - clamp01(m.getBmi(), m.getBmiLowerLimit(), m.getBmiUpperLimit()),
                clamp01(m.getEcwTbw(), 0.32, 0.39),
                clamp01(m.getV50khzWholeBodyPhaseAngle(), 3.0, 8.0)
        };
        String[] labels = {"Score", "MMS", "Graisse(inv.)", "IMC(inv.)", "Hydrat.", "Phase"};
        String[] values = {
                fmt(m.getInbodyScore()),
                fmt(m.getSkeletalMuscleMass()) + " kg",
                fmt(m.getPercentBodyFat()) + "%",
                fmt(m.getBmi()),
                fmt3(m.getEcwTbw()),
                fmt(m.getV50khzWholeBodyPhaseAngle()) + "°"
        };

        try {
            float size = 110f;
            PdfFormXObject xobj = new PdfFormXObject(new Rectangle(size, size));
            PdfCanvas pc = new PdfCanvas(xobj, pdf);
            float cx = size / 2f, cy = size / 2f, maxR = size / 2f - 14f;

            // Anneaux concentriques
            for (float ring : new float[]{1f, 0.66f, 0.33f}) {
                pc.setFillColor(ring > 0.66f ? new DeviceRgb(230,230,230)
                        : ring > 0.33f ? new DeviceRgb(215,215,215)
                        : new DeviceRgb(200,200,200));
                pc.setStrokeColor(LIGHT_GRAY);
                pc.setLineWidth(0.3f);
                float r = maxR * ring;
                pc.moveTo(cx + r * Math.cos(Math.PI/2), cy + r * Math.sin(Math.PI/2));
                for (int i = 1; i <= 6; i++) {
                    double angle = Math.PI/2 + i * 2 * Math.PI / 6;
                    pc.lineTo(cx + r * Math.cos(angle), cy + r * Math.sin(angle));
                }
                pc.fillStroke();
            }

            // Rayons
            pc.setStrokeColor(LIGHT_GRAY); pc.setLineWidth(0.3f);
            for (int i = 0; i < 6; i++) {
                double angle = Math.PI/2 + i * 2 * Math.PI / 6;
                pc.moveTo(cx, cy);
                pc.lineTo(cx + maxR * Math.cos(angle), cy + maxR * Math.sin(angle));
                pc.stroke();
            }

            // Polygone données
            pc.setFillColor(new DeviceRgb(150, 150, 150));
            pc.setStrokeColor(DARK); pc.setLineWidth(1.5f);
            for (int i = 0; i < 6; i++) {
                double angle = Math.PI/2 + i * 2 * Math.PI / 6;
                float r = (float)(axes[i] * maxR);
                if (i == 0) pc.moveTo(cx + r * Math.cos(angle), cy + r * Math.sin(angle));
                else        pc.lineTo(cx + r * Math.cos(angle), cy + r * Math.sin(angle));
            }
            pc.closePath(); pc.fillStroke();

            // Points
            pc.setFillColor(DARK);
            for (int i = 0; i < 6; i++) {
                double angle = Math.PI/2 + i * 2 * Math.PI / 6;
                float r = (float)(axes[i] * maxR);
                pc.circle(cx + r * Math.cos(angle), cy + r * Math.sin(angle), 2.5f);
                pc.fill();
            }

            // Labels axes
            PdfFont f = PdfFontFactory.createFont(StandardFonts.HELVETICA);
            pc.setFillColor(DARK_GRAY);
            for (int i = 0; i < 6; i++) {
                double angle = Math.PI/2 + i * 2 * Math.PI / 6;
                float lr = maxR + 10f;
                pc.beginText(); pc.setFontAndSize(f, 5f);
                pc.moveText(cx + lr * Math.cos(angle) - 8, cy + lr * Math.sin(angle) - 3);
                pc.showText(labels[i]); pc.endText();
            }
            pc.release();

            com.itextpdf.layout.element.Image img = new com.itextpdf.layout.element.Image(xobj)
                    .setWidth(size).setHeight(size);
            cc.add(img);
        } catch (Exception e) {
            log.warn("Radar chart error: {}", e.getMessage());
        }

        // Tableau des valeurs
        Table vt = new Table(UnitValue.createPercentArray(new float[]{50, 25, 25}))
                .setWidth(UnitValue.createPercentValue(100)).setMarginTop(3);
        vt.addCell(hdrCell("Indicateur", regular));
        vt.addCell(hdrCell("Valeur", regular));
        vt.addCell(hdrCell("Norme", regular));
        String[] names = {"Score InBody", "MMS", "TGC", "IMC", "ECW/TBW", "Angle phase"};
        String[] norms = {"60–80",
                fmt(m.getSmmLowerLimit()) + "–" + fmt(m.getSmmUpperLimit()),
                fmt(m.getPbfLowerLimit()) + "–" + fmt(m.getPbfUpperLimit()),
                fmt(m.getBmiLowerLimit()) + "–" + fmt(m.getBmiUpperLimit()),
                "0,32–0,39", "3,5–7,0°"};
        for (int i = 0; i < 6; i++) {
            DeviceRgb bg = i % 2 == 0 ? STRIPE_A : STRIPE_B;
            vt.addCell(new Cell().setBackgroundColor(bg).setBorder(Border.NO_BORDER).setPadding(2).add(p(names[i], regular, 6)));
            vt.addCell(new Cell().setBackgroundColor(bg).setBorder(Border.NO_BORDER).setPadding(2).setTextAlignment(TextAlignment.CENTER).add(p(values[i], bold, 6)));
            vt.addCell(new Cell().setBackgroundColor(bg).setBorder(Border.NO_BORDER).setPadding(2).setTextAlignment(TextAlignment.CENTER).add(p(norms[i], regular, 5).setFontColor(MID_GRAY)));
        }
        cc.add(vt);
        s.addCell(cc);
        return s;
    }

    private Table secDonutComposition(InBodyMeasurement m, PdfFont bold, PdfFont regular, PdfDocument pdf) {
        Table s = wrap();
        s.addCell(secTitleCell("Répartition de la composition corporelle", bold));
        Cell cc = nb(3);

        double total = safeD(m.getWeight()); if (total <= 0) total = 1;
        double water = safeD(m.getTotalBodyWater());
        double prot  = safeD(m.getProtein());
        double miner = safeD(m.getMinerals());
        double fat   = safeD(m.getBodyFatMass());
        double other = Math.max(0, total - water - prot - miner - fat);
        double[] kgs  = {water, prot, miner, fat, other};
        float[] props = new float[5];
        for (int i = 0; i < 5; i++) props[i] = (float)(kgs[i] / total * 100);
        DeviceRgb[] colors = {
                new DeviceRgb(60, 60, 60),
                new DeviceRgb(100, 100, 100),
                new DeviceRgb(140, 140, 140),
                new DeviceRgb(180, 180, 180),
                new DeviceRgb(210, 210, 210)
        };
        String[] lbls = {"Eau", "Protéines", "Minéraux", "Graisse", "Autre"};

        try {
            float ps = 90f;
            PdfFormXObject pie = new PdfFormXObject(new Rectangle(ps, ps));
            PdfCanvas pc = new PdfCanvas(pie, pdf);
            float cx = ps/2f, cy = ps/2f, r = ps/2f - 4f;
            double startA = Math.PI / 2;
            for (int i = 0; i < 5; i++) {
                double sweep = props[i] / 100.0 * 2 * Math.PI;
                double endA  = startA - sweep;
                pc.setFillColor(colors[i]); pc.setStrokeColor(WHITE); pc.setLineWidth(0.8f);
                pc.moveTo(cx, cy);
                int segs = Math.max(1, (int)(sweep / (Math.PI/4)) + 1);
                double ss = sweep / segs;
                for (int sg = 0; sg < segs; sg++) {
                    double a0 = startA - sg * ss, a1 = a0 - ss;
                    double k = 4.0/3.0 * Math.tan(ss / 4.0);
                    pc.curveTo(cx + r*Math.cos(a0) - k*r*Math.sin(a0), cy + r*Math.sin(a0) + k*r*Math.cos(a0),
                            cx + r*Math.cos(a1) + k*r*Math.sin(a1), cy + r*Math.sin(a1) - k*r*Math.cos(a1),
                            cx + r*Math.cos(a1), cy + r*Math.sin(a1));
                }
                pc.closePath(); pc.fillStroke();
                startA = endA;
            }
            pc.release();

            Table row = new Table(UnitValue.createPercentArray(new float[]{ps + 8, 100})).setWidth(UnitValue.createPercentValue(100));
            row.addCell(nb(1).add(new com.itextpdf.layout.element.Image(pie).setWidth(ps).setHeight(ps)));
            Table leg = new Table(UnitValue.createPercentArray(new float[]{12, 55, 33})).setWidth(UnitValue.createPercentValue(100));
            leg.addCell(hdrCell("", regular)); leg.addCell(hdrCell("Composant", regular)); leg.addCell(hdrCell("kg (%)", regular));
            for (int i = 0; i < 5; i++) {
                leg.addCell(new Cell().setBackgroundColor(colors[i]).setHeight(10).setBorder(Border.NO_BORDER));
                leg.addCell(nb(1).add(p(lbls[i], regular, 7)));
                leg.addCell(nb(1).setTextAlignment(TextAlignment.RIGHT)
                        .add(p(fmt(kgs[i]) + " (" + fmt((double)props[i]) + "%)", bold, 6.5f)));
            }
            row.addCell(nb(1).add(leg));
            cc.add(row);
        } catch (Exception e) { log.warn("Pie chart error: {}", e.getMessage()); }

        cc.add(p("Poids : " + fmt(m.getWeight()) + " kg  |  Masse maigre : " +
                        fmt(m.getFatFreeMass()) + " kg  |  TGC : " + fmt(m.getPercentBodyFat()) + "%",
                bold, 6.5f).setFontColor(DARK_GRAY));
        s.addCell(cc);
        return s;
    }

    private Table secEquilibreSegmentaire(InBodyMeasurement m, PdfFont bold, PdfFont regular, PdfDocument pdf) {
        Table s = wrap();
        s.addCell(secTitleCell("Équilibre segmentaire gauche / droite", bold));
