        t.addCell(hdrCell("← Gauche", regular));
        t.addCell(hdrCell("", regular));
        t.addCell(hdrCell("Droite →", regular));
        symRow(t, "Bras — Masse Maigre",  m.getFfmLeftArm(),      m.getFfmRightArm(),      regular, bold);
        symRow(t, "Bras — Eau (L)",       m.getTbwLeftArm(),      m.getTbwRightArm(),      regular, bold);
        symRow(t, "Jambe — Masse Maigre", m.getFfmLeftLeg(),      m.getFfmRightLeg(),      regular, bold);
        symRow(t, "Jambe — Eau (L)",      m.getTbwLeftLeg(),      m.getTbwRightLeg(),      regular, bold);
        symRow(t, "Bras — Ratio EEC",     m.getEcwTbwOfLeftArm(), m.getEcwTbwOfRightArm(), regular, bold);
        symRow(t, "Jambe — Ratio EEC",    m.getEcwTbwOfLeftLeg(), m.getEcwTbwOfRightLeg(), regular, bold);
        cc.add(t);
        cc.add(p("Note : asymétrie > 5% mérite une attention clinique.", regular, 5.5f).setFontColor(MID_GRAY));
        s.addCell(cc);
        return s;
    }

    private void symRow(Table t, String label, Double left, Double right, PdfFont regular, PdfFont bold) {
        double l = safeD(left), r = safeD(right), total = l + r;
        float lPct = total > 0 ? (float)(l / total * 100) : 50f;
        float diff = Math.abs(lPct - 50f);
        DeviceRgb bc = diff < 3 ? new DeviceRgb(80,80,80) : diff < 8 ? new DeviceRgb(130,130,130) : LIGHT_GRAY;

        t.addCell(nb(1).add(p(label, regular, 6)));
        float lf = Math.max(1, lPct), le = Math.max(1, 100 - lPct);
        Table lb = new Table(UnitValue.createPercentArray(new float[]{le, lf})).setWidth(UnitValue.createPercentValue(100));
        lb.addCell(new Cell().setHeight(7).setBackgroundColor(BAR_BG).setBorder(Border.NO_BORDER));
        lb.addCell(new Cell().setHeight(7).setBackgroundColor(bc).setBorder(Border.NO_BORDER));
        Cell lc = nb(1).add(lb); lc.add(p(fmt(left), bold, 5.5f).setTextAlignment(TextAlignment.RIGHT));
        t.addCell(lc);
        t.addCell(nb(0).setTextAlignment(TextAlignment.CENTER)
                .add(p(diff < 2 ? "=" : "≠", bold, 7).setFontColor(diff < 2 ? DARK : MID_GRAY)));
        float rf = Math.max(1, 100 - lPct), re = Math.max(1, lPct);
        Table rb = new Table(UnitValue.createPercentArray(new float[]{rf, re})).setWidth(UnitValue.createPercentValue(100));
        rb.addCell(new Cell().setHeight(7).setBackgroundColor(bc).setBorder(Border.NO_BORDER));
        rb.addCell(new Cell().setHeight(7).setBackgroundColor(BAR_BG).setBorder(Border.NO_BORDER));
        Cell rc = nb(1).add(rb); rc.add(p(fmt(right), bold, 5.5f));
        t.addCell(rc);
    }

    private Table secInterpretationClinique(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Interprétation clinique automatisée", bold));
        Cell cc = nb(4).setBackgroundColor(VLIGHT_GRAY);
        Table t = twoCol(50, 50);
        Cell lc = nb(3), rc = nb(3);

        Double bmi = m.getBmi();
        String imcCat = bmi == null ? "N/D"
                : bmi < 18.5 ? "Insuffisance pondérale" : bmi < 25 ? "Poids normal"
                : bmi < 30   ? "Surpoids" : bmi < 35 ? "Obésité classe I"
                : bmi < 40   ? "Obésité classe II" : "Obésité classe III";

        Double vfa = m.getVfaVisceralFatArea();
        String vfaRisk = vfa == null ? "-" : vfa < 100 ? "Risque faible" : vfa < 160 ? "Risque modéré" : "Risque élevé";

        Double smm = m.getSkeletalMuscleMass();
        String smmStat = smm == null ? "-"
                : (m.getSmmLowerLimit() != null && smm < m.getSmmLowerLimit()) ? "Insuffisante"
                : (m.getSmmUpperLimit() != null && smm > m.getSmmUpperLimit()) ? "Élevée" : "Normale";

        Double ecw = m.getEcwTbw();
        String ecwStat = ecw == null ? "-"
                : ecw < 0.36 ? "Hydratation basse"
                : ecw > 0.40 ? "Rétention possible"
                : "Équilibre normal";

        lc.add(p("Statut pondéral :", bold, 7)); lc.add(p(imcCat, bold, 8)); lc.add(spacer(3));
        lc.add(p("Masse musculaire :", bold, 7)); lc.add(p(smmStat, bold, 8)); lc.add(spacer(3));
        lc.add(p("Score InBody :", bold, 7));
        lc.add(p(fmt(m.getInbodyScore()) + " / 100 — " + scoreLabel(m.getInbodyScore()), bold, 8));

        rc.add(p("Graisse viscérale :", bold, 7)); rc.add(p(vfaRisk + " (" + fmt(vfa) + " cm²)", bold, 8)); rc.add(spacer(3));
        rc.add(p("Équilibre hydrique :", bold, 7)); rc.add(p(ecwStat + " (" + fmt3(ecw) + ")", bold, 8)); rc.add(spacer(3));
        rc.add(p("Angle de phase :", bold, 7));
        rc.add(p(fmt(m.getV50khzWholeBodyPhaseAngle()) + "° — " + phaseLabel(m.getV50khzWholeBodyPhaseAngle()), bold, 8));

        t.addCell(lc); t.addCell(rc);
        cc.add(t);
        s.addCell(cc);
        return s;
    }

    private Table secRecommandationsEnrichies(InBodyMeasurement m, PdfFont bold, PdfFont regular) {
        Table s = wrap();
        s.addCell(secTitleCell("Objectifs & Recommandations Personnalisées", bold));

        Table t = new Table(UnitValue.createPercentArray(new float[]{33, 33, 34}))
                .setWidth(UnitValue.createPercentValue(100));

        // Col 1 : poids
        Cell c1 = new Cell().setBackgroundColor(VLIGHT_GRAY)
                .setBorder(new SolidBorder(LIGHT_GRAY, 0.5f)).setPadding(5);
        c1.add(p("Objectifs pondéraux", bold, 7.5f));
        c1.add(spacer(3));
        c1.add(p("Poids cible : " + fmt(m.getTargetWeight()) + " kg", regular, 7));
        c1.add(p("Poids actuel : " + fmt(m.getWeight()) + " kg", regular, 7));
        double diff = safeD(m.getWeight()) - safeD(m.getTargetWeight());
        c1.add(p("Différence : " + (diff > 0 ? "-" : "+") + fmt(Math.abs(diff)) + " kg", bold, 7));
        c1.add(spacer(3));
        c1.add(p("Contrôle masse grasse : " + fmt(m.getBfmControl()) + " kg", regular, 6.5f));
        c1.add(p("Contrôle masse maigre : " + fmt(m.getFfmControl()) + " kg", regular, 6.5f));
        t.addCell(c1);

        // Col 2 : énergie
        Cell c2 = new Cell().setBackgroundColor(VLIGHT_GRAY)
                .setBorder(new SolidBorder(LIGHT_GRAY, 0.5f)).setPadding(5);
        c2.add(p("Bilan énergétique", bold, 7.5f));
        c2.add(spacer(3));
        c2.add(p("Métabolisme de base :", regular, 7));
        c2.add(p(fmt(m.getBmrBasalMetabolicRate()) + " kcal/jour", bold, 8));
        c2.add(spacer(3));
        c2.add(p("Apport recommandé :", regular, 7));
        c2.add(p(fmt(m.getRecommendedCalorieIntake()) + " kcal/jour", bold, 8));
        c2.add(spacer(3));
        c2.add(p("Norme : " + range(m.getLowerLimitBmrNormalRange(), m.getUpperLimitBmrNormalRange()) + " kcal",
                regular, 6).setFontColor(MID_GRAY));
        t.addCell(c2);

        // Col 3 : conseils
        Cell c3 = new Cell().setBackgroundColor(VLIGHT_GRAY)
                .setBorder(new SolidBorder(LIGHT_GRAY, 0.5f)).setPadding(5);
        c3.add(p("Conseils généraux", bold, 7.5f));
        c3.add(spacer(3));
        if (m.getPercentBodyFat() != null && m.getPbfUpperLimit() != null
                && m.getPercentBodyFat() > m.getPbfUpperLimit())
            c3.add(bullet("Réduire les graisses saturées.", regular));
        if (m.getSkeletalMuscleMass() != null && m.getSmmLowerLimit() != null
                && m.getSkeletalMuscleMass() < m.getSmmLowerLimit())
            c3.add(bullet("Augmenter la résistance musculaire.", regular));
        if (m.getVfaVisceralFatArea() != null && m.getVfaVisceralFatArea() > 100)
            c3.add(bullet("Exercice cardio 150 min/semaine.", regular));
        if (safeD(m.getEcwTbw()) > 0.40)
            c3.add(bullet("Surveiller la rétention hydrique.", regular));
        c3.add(bullet("Maintenir un suivi trimestriel.", regular));
        c3.add(bullet("Boire 1,5–2 L d'eau par jour.", regular));
        t.addCell(c3);

        s.addCell(nb(0).add(t));
        return s;
    }

    // ══════════════════════════════════════════════════════════════════════════
    // PRIMITIVES GRAPHIQUES
    // ══════════════════════════════════════════════════════════════════════════

    /**
     * Barre colorée universelle (reproduit exactement la barre originale) :
     *  - Graduation numérique sur le dessus
     *  - 3 zones : Inférieur | Normal | Supérieur
     *  - Marqueur ▼ à la position de la valeur
     *  - Valeur numérique centrée sous le marqueur
     */
    private Table buildColorBar(Double value, Double lo, Double hi,
                                double sMin, double sMax,
                                int steps, PdfFont regular) {
        Table wrap = new Table(UnitValue.createPercentArray(new float[]{100}))
                .setWidth(UnitValue.createPercentValue(100));
        try {
            double range  = sMax - sMin; if (range <= 0) range = 1;
            double loSafe = lo != null ? lo : sMin + range * 0.3;
            double hiSafe = hi != null ? hi : sMin + range * 0.7;

            // Graduation
            Table scale = new Table(UnitValue.createPercentArray(new float[steps + 1])).setWidth(UnitValue.createPercentValue(100));
            double step = range / steps;
            for (int i = 0; i <= steps; i++) {
                double tv = sMin + i * step;
                String ts = fmtScaleTick(tv);
                scale.addCell(new Cell().setBorder(Border.NO_BORDER).setPadding(0)
                        .setTextAlignment(i == 0 ? TextAlignment.LEFT
                                : i == steps ? TextAlignment.RIGHT : TextAlignment.CENTER)
                        .add(p(ts, regular, 5).setFontColor(MID_GRAY)));
            }
            wrap.addCell(nb(0).add(scale));

            // Calcul positions %
            float loP  = clampPct((loSafe - sMin) / range * 100);
            float hiP  = clampPct((hiSafe - sMin) / range * 100);
            float valP = value != null ? clampPct((value - sMin) / range * 100) : 50f;

            float s1 = Math.max(0.5f, loP);
            float s2 = Math.max(0.5f, hiP - loP);
            float s3 = Math.max(0.5f, 100f - hiP);

            // Barre 3 zones colorées : rouge (inférieur) | bleu (normal) | vert (supérieur)
            Table bar = new Table(UnitValue.createPercentArray(new float[]{s1, s2, s3})).setWidth(UnitValue.createPercentValue(100));
            bar.addCell(new Cell().setHeight(7).setBackgroundColor(ZONE_LOW).setBorder(Border.NO_BORDER));
            bar.addCell(new Cell().setHeight(7).setBackgroundColor(ZONE_NORMAL).setBorder(Border.NO_BORDER));
            bar.addCell(new Cell().setHeight(7).setBackgroundColor(ZONE_HIGH).setBorder(Border.NO_BORDER));
            wrap.addCell(nb(0).add(bar));

            // Marqueur ▼ coloré selon le score
            DeviceRgb markerColor = (value != null && value < loSafe) ? FILL_LOW
                    : (value != null && value > hiSafe) ? FILL_HIGH : FILL_NORMAL;
            float ml = Math.max(0f, valP - 3f);
            float mr = Math.max(0.5f, 100f - valP - 3f);
            Table mk = new Table(UnitValue.createPercentArray(new float[]{ml, 6, mr})).setWidth(UnitValue.createPercentValue(100));
            mk.addCell(nb(0));
            mk.addCell(nb(0).setTextAlignment(TextAlignment.CENTER)
                    .add(p("▼", regular, 7).setFontColor(markerColor)));
            mk.addCell(nb(0));
            wrap.addCell(nb(0).add(mk));

            // Valeur sous le marqueur (même couleur que le marqueur)
            wrap.addCell(nb(0).setTextAlignment(TextAlignment.CENTER)
                    .add(p(fmt(value), regular, 6).setFontColor(markerColor)));

        } catch (Exception e) {
            log.warn("colorBar error: {}", e.getMessage());
        }
        return wrap;
    }

    /**
     * Barre de pourcentage segmentaire (80–120%)
     * Zones : <90% | 90–110% | >110%
     */
    private Table buildPercentBar(Double pct, double pctMin, double pctMax, PdfFont regular) {
        Table wrap = new Table(UnitValue.createPercentArray(new float[]{100}))
                .setWidth(UnitValue.createPercentValue(100));

        // Graduation
        Table scale = new Table(UnitValue.createPercentArray(new float[]{20, 20, 20, 20, 20})).setWidth(UnitValue.createPercentValue(100));
        for (String tick : new String[]{"80", "90", "100", "110", "120"})
            scale.addCell(nb(0).setTextAlignment(TextAlignment.CENTER)
                    .add(p(tick, regular, 5).setFontColor(MID_GRAY)));
        wrap.addCell(nb(0).add(scale));

        // Barre zones colorées : rouge | bleu | vert
        Table bar = new Table(UnitValue.createPercentArray(new float[]{20, 60, 20})).setWidth(UnitValue.createPercentValue(100));
        bar.addCell(new Cell().setHeight(7).setBackgroundColor(ZONE_LOW).setBorder(Border.NO_BORDER));
        bar.addCell(new Cell().setHeight(7).setBackgroundColor(ZONE_NORMAL).setBorder(Border.NO_BORDER));
        bar.addCell(new Cell().setHeight(7).setBackgroundColor(ZONE_HIGH).setBorder(Border.NO_BORDER));
        wrap.addCell(nb(0).add(bar));

        // Marqueur coloré selon position
        double sp = pct != null ? pct : 100;
        float pos = clampPct((sp - pctMin) / (pctMax - pctMin) * 100);
        DeviceRgb pBarColor = (sp < 90) ? FILL_LOW : (sp > 110) ? FILL_HIGH : FILL_NORMAL;
        float ml = Math.max(0f, pos - 3f), mr = Math.max(0.5f, 100f - pos - 3f);
        Table mk = new Table(UnitValue.createPercentArray(new float[]{ml, 6, mr})).setWidth(UnitValue.createPercentValue(100));
        mk.addCell(nb(0));
        mk.addCell(nb(0).setTextAlignment(TextAlignment.CENTER).add(p("▼", regular, 7).setFontColor(pBarColor)));
        mk.addCell(nb(0));
        wrap.addCell(nb(0).add(mk));
        return wrap;
    }

    /**
     * CORRECTION 1 — Barre segmentaire masse maigre (large, identique à l'original).
     * Graduation sur 5 points : 80 / 90 / 100 / 110 / 120 %
     * Barre pleine noire avec zones gris clair aux extrémités.
     * Marqueur ▼ double : un pour le poids idéal (ligne de référence) et
     * un pour la valeur actuelle (position réelle).
     * La hauteur de la barre est plus grande (10px) pour ressembler aux barres
     * "très larges" de l'original.
     */
    private Table buildSegMaigreBar(Double pct, double pctMin, double pctMax, PdfFont regular) {
        Table wrap = new Table(UnitValue.createPercentArray(new float[]{100}))
                .setWidth(UnitValue.createPercentValue(100));

        // Graduation : 5 ticks de 80 à 120
        Table scale = new Table(UnitValue.createPercentArray(new float[]{20, 20, 20, 20, 20})).setWidth(UnitValue.createPercentValue(100));
        for (String tick : new String[]{"80", "90", "100", "110", "120"})
            scale.addCell(nb(0).setTextAlignment(TextAlignment.CENTER)
                    .add(p(tick, regular, 5).setFontColor(MID_GRAY)));
        wrap.addCell(nb(0).add(scale));

        // Barre haute (10px) zones colorées : rouge | bleu | vert
        Table bar = new Table(UnitValue.createPercentArray(new float[]{20, 60, 20})).setWidth(UnitValue.createPercentValue(100));
        bar.addCell(new Cell().setHeight(10).setBackgroundColor(ZONE_LOW).setBorder(Border.NO_BORDER));
        bar.addCell(new Cell().setHeight(10).setBackgroundColor(ZONE_NORMAL).setBorder(Border.NO_BORDER));
        bar.addCell(new Cell().setHeight(10).setBackgroundColor(ZONE_HIGH).setBorder(Border.NO_BORDER));
        wrap.addCell(nb(0).add(bar));

        // Marqueur ▼ coloré selon la zone
        double sp  = pct != null ? pct : 100;
        float pos  = clampPct((sp - pctMin) / (pctMax - pctMin) * 100);
        DeviceRgb segColor = (sp < 90) ? FILL_LOW : (sp > 110) ? FILL_HIGH : FILL_NORMAL;
        float ml   = Math.max(0f, pos - 3f);
        float mr   = Math.max(0.5f, 100f - pos - 3f);
        Table mk = new Table(UnitValue.createPercentArray(new float[]{ml, 6, mr})).setWidth(UnitValue.createPercentValue(100));
        mk.addCell(nb(0));
        mk.addCell(nb(0).setTextAlignment(TextAlignment.CENTER).add(p("▼", regular, 8).setFontColor(segColor)));
        mk.addCell(nb(0));
        wrap.addCell(nb(0).add(mk));
        return wrap;
    }

    // ══════════════════════════════════════════════════════════════════════════
    // UTILITAIRES DE MISE EN PAGE
    // ══════════════════════════════════════════════════════════════════════════

    private Table twoCol(float l, float r) {
        return new Table(UnitValue.createPercentArray(new float[]{l, r}))
                .setWidth(UnitValue.createPercentValue(100)).setMarginTop(1);
    }

    private Table wrap() {
        return new Table(UnitValue.createPercentArray(new float[]{100}))
                .setWidth(UnitValue.createPercentValue(100))
                .setMarginBottom(3)
                .setBorder(new SolidBorder(LIGHT_GRAY, 0.4f));
    }

    private Table resumeTable() {
        return new Table(UnitValue.createPercentArray(new float[]{50, 25, 25}))
                .setWidth(UnitValue.createPercentValue(100));
    }

    private Cell secTitleCell(String text, PdfFont bold) {
        return new Cell()
                .setBackgroundColor(new DeviceRgb(50, 110, 185))   // bleu InBody
                .setBorder(Border.NO_BORDER)
                .setBorderBottom(new SolidBorder(new DeviceRgb(30, 80, 150), 0.8f))
                .setPadding(3)
                .add(new Paragraph(text).setFont(bold).setFontSize(7.5f)
                        .setFontColor(WHITE).setMargin(0));
    }

    private Cell hdrCell(String text, PdfFont regular) {
        return new Cell().setBackgroundColor(HDR_BG)
                .setBorder(new SolidBorder(new DeviceRgb(180, 210, 235), 0.3f)).setPadding(1)
                .setTextAlignment(TextAlignment.CENTER)
                .add(p(text, regular, 5.5f).setFontColor(new DeviceRgb(50, 90, 150)));
    }

    private Cell nb()      { return new Cell().setBorder(Border.NO_BORDER); }
    private Cell nb(int p) { return new Cell().setBorder(Border.NO_BORDER).setPadding(p); }

    private Paragraph p(String text, PdfFont font, float size) {
        return new Paragraph(text).setFont(font).setFontSize(size).setMargin(0);
    }

    private Paragraph spacer(float h) {
        return new Paragraph(" ").setFontSize(1).setMarginTop(h / 2).setMarginBottom(h / 2);
    }

    private Paragraph bullet(String text, PdfFont regular) {
        return new Paragraph("• " + text).setFont(regular).setFontSize(6.5f).setMargin(0).setMarginTop(2);
    }

    // ══════════════════════════════════════════════════════════════════════════
    // FORMATTERS
    // ══════════════════════════════════════════════════════════════════════════

    private String fmt(Double v) {
        if (v == null) return "-";
        if (v == Math.floor(v) && !Double.isInfinite(v)) return String.valueOf(v.intValue());
        return String.format("%.1f", v);
    }

    private String fmt(Integer v) { return v != null ? String.valueOf(v) : "-"; }

    private String fmt3(Double v) { return v == null ? "-" : String.format("%.3f", v); }

    private String fmtPct(Double v) { return v == null ? "-" : fmt(v); }

    private String fmtScaleTick(double tv) {
        if (tv == Math.floor(tv) && !Double.isInfinite(tv)) return String.valueOf((int) tv);
        return String.format("%.3f", tv).replaceAll("0+$", "").replaceAll("\\.$", "");
    }

    private String range(Double lo, Double hi) {
        if (lo == null && hi == null) return "";
        return "( " + fmt(lo) + " ~ " + fmt(hi) + " )";
    }

    private String safe(String v) { return v != null ? v : "-"; }

    private double safeD(Double v) { return v != null ? v : 0.0; }

    private String fmtGender(String g) {
        if (g == null) return "-";
        return (g.equalsIgnoreCase("Female") || g.equalsIgnoreCase("F")) ? "Femme" : "Homme";
    }

    private float clampPct(double v) { return (float) Math.max(0.5, Math.min(99.5, v)); }

    private double minOf(double[] arr) { double m = Double.MAX_VALUE; for (double v : arr) if (v < m) m = v; return m; }
    private double maxOf(double[] arr) { double m = -Double.MAX_VALUE; for (double v : arr) if (v > m) m = v; return m; }

    private double clamp01(Double val, Double lo, Double hi) {
        if (val == null || lo == null || hi == null) return 0.5;
        double range = hi - lo; if (range == 0) return 0.5;
        return Math.max(0, Math.min(1, (val - lo) / range));
    }
    private double clamp01(Double val, double lo, double hi) { return clamp01(val, lo, hi); }
    private double clamp01(Integer val, int lo, int hi) {
        return clamp01(val != null ? val.doubleValue() : null, (double) lo, (double) hi);
    }

    private String scoreLabel(Integer s) {
        if (s == null) return "-";
        return s >= 90 ? "Excellent" : s >= 80 ? "Très bien" : s >= 70 ? "Bien" : s >= 60 ? "Moyen" : "À améliorer";
    }

    private String phaseLabel(Double deg) {
        if (deg == null) return "-";
        return deg >= 7 ? "Excellent" : deg >= 5 ? "Normal" : deg >= 3.5 ? "Limite basse" : "Faible";
    }
}
